import androidx.compose.ui.test.*
import androidx.compose.ui.test.ExperimentalTestApi
import androidx.compose.ui.test.runComposeUiTest
import java.io.ByteArrayOutputStream
import java.io.PrintStream

{{ STUDENT_ANSWER }}

data class __CrUiTestResult(
    val name: String,
    val expected: String,
    val got: String,
    val passed: Boolean
)

fun __crJson(value: String): String =
    "\"" + value
        .replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t") + "\""

fun __crClip(value: String, limit: Int = 1200): String =
    if (value.length <= limit) value else value.take(limit) + "\n..."

fun __crCaptureText(buffer: ByteArrayOutputStream): String =
    String(buffer.toByteArray(), Charsets.UTF_8).trim()

fun __crThrowableSummary(throwable: Throwable): String {
    val className = throwable::class.simpleName ?: "Failure"
    val message = throwable.message?.trim().orEmpty()
    val cause = throwable.cause
    val causeText = if (cause == null) {
        ""
    } else {
        "\nCaused by: " + (cause::class.simpleName ?: "Failure") + ": " + cause.message.orEmpty()
    }
    val summary = if (message.isEmpty()) className else "$className: $message"
    return summary + causeText
}

@OptIn(ExperimentalTestApi::class)
fun main() {
    val __crOriginalOut = System.out
    val __crOriginalErr = System.err
    val __crResults = mutableListOf<__CrUiTestResult>()

{% for testCase in TESTCASES %}
    run {
        {% if QUESTION.parameters.showtestcode | default(false) %}
        val __crName = {{ testCase.testcode | json_encode | raw }}
        {% else %}
        {% if testCase.expected is defined and testCase.expected|trim %}
        val __crName = {{ testCase.expected | json_encode | raw }}
        {% else %}
        val __crName = "Test {{ loop.index }}"
        {% endif %}
        {% endif %}
        var __crPassText: String? = null
        var __crFailText: String? = null
        val __crCapture = ByteArrayOutputStream()
        System.setOut(PrintStream(__crCapture, true, Charsets.UTF_8.name()))
        System.setErr(PrintStream(__crCapture, true, Charsets.UTF_8.name()))
        try {
            runComposeUiTest {
                val __crComposeScope = this
                fun ktTest(
                    block: ComposeUiTest.() -> Unit,
                    passText: String? = null,
                    failText: String? = null
                ) {
                    __crPassText = passText ?: "Pass"
                    __crFailText = failText
                    __crComposeScope.block()
                }
{{ testCase.testcode }}
            }
            val __crOutput = __crCaptureText(__crCapture)
            val __crExpected = __crPassText ?: "Pass"
            val __crPassMessage = __crPassText ?: "Pass"
            val __crGot = if (__crOutput.isEmpty()) {
                __crPassMessage
            } else {
                __crPassMessage + "\nOutput:\n" + __crClip(__crOutput)
            }
            __crResults += __CrUiTestResult(__crName, __crExpected, __crGot, true)
        } catch (__crThrowable: Throwable) {
            val __crOutput = __crCaptureText(__crCapture)
            val __crExpected = __crPassText ?: "Pass"
            val __crMessage = __crFailText ?: __crClip(__crThrowableSummary(__crThrowable), 2000)
            val __crGot = if (__crOutput.isEmpty()) {
                __crMessage
            } else {
                __crMessage + "\nOutput:\n" + __crClip(__crOutput)
            }
            __crResults += __CrUiTestResult(__crName, __crExpected, __crGot, false)
        } finally {
            System.out.flush()
            System.err.flush()
            System.setOut(__crOriginalOut)
            System.setErr(__crOriginalErr)
        }
    }
{% endfor %}

    val __crPassed = __crResults.count { it.passed }
    val __crFraction = if (__crResults.isEmpty()) 0.0 else __crPassed.toDouble() / __crResults.size
    val __crRows = __crResults.joinToString(",") {
        "[" + listOf(__crJson(it.name), __crJson(it.expected), __crJson(it.got), it.passed.toString()).joinToString(",") + "]"
    }
    val __crResultJson = buildString {
        append("{\"fraction\":")
        append(__crFraction)
        append(",\"testresults\":[[\"Test\",\"Expected\",\"Got\",\"iscorrect\"]")
        if (__crRows.isNotEmpty()) {
            append(",")
            append(__crRows)
        }
        append("]}")
    }
    __crOriginalOut.println(__crResultJson)
}

"""The template for a "write a program" question type that accepts answers
    in C, C++, Java,Python3,Perl,PHP,Ruby,JavaScript,C# or Golang according to the value in the language select
    dropdown menu.
"""

import subprocess
import re
student_answer = """{{ STUDENT_ANSWER | e('py') }}"""
language = """{{ ANSWER_LANGUAGE | e('py') }}""".lower()
language_extension_map = {
      'c':'c'
    , 'cpp':'cpp'
    , 'java':'java'
    , 'python3':'py'
    , 'perl':'pl'
    , 'php':'php'
    , 'ruby':'rb'
    , 'javascript':'js'
    , 'c#':'cs'
    , 'golang':'go'


}

if language not in language_extension_map.keys():
    raise Exception('Error in question. Unknown/unexpected language ({})'.format(language))

if language == 'java':
    # Need to determine public class name in order to name output file. Sigh.
    # The best I can be bothered to do is to use a regular expression match.
    match = re.search(r'public\s+class\s+([_a-zA-Z][_a-zA-Z0-9]*)', student_answer, re.DOTALL | re.MULTILINE)
    if match is None:
        raise Exception("Unable to determine class name. Does the file include 'public class name'?")
    classname = match.group(1)
    filename = classname + '.java'
elif language == 'golang':
    filename = 'tester.' + language_extension_map[language]
else:
    filename = '__tester__.' + language_extension_map[language]

# Write the student code to a file

with open(filename, "w") as src:
    print(student_answer, file=src)

# Compile C, C++ and Java
if language == 'c':
    cflags = "-std=c99 -Wall -Werror"
    return_code = subprocess.call("gcc {0} -o __tester__ __tester__.c".format(cflags).split())
    if return_code != 0:
        raise Exception("** Compilation failed. Testing aborted **")
    exec_command = ["./__tester__"]
elif language == 'cpp':
    cppflags = "-Wall -Werror"
    return_code = subprocess.call("g++ {0} -o __tester__ __tester__.cpp".format(cppflags).split())
    if return_code != 0:
        raise Exception("** Compilation failed. Testing aborted **")
    exec_command = ["./__tester__"]
elif language == 'java':
    return_code = subprocess.call(['javac', "-J-Xss64m", "-J-Xmx4g", filename])
    if return_code != 0:
        raise Exception("** Compilation failed. Testing aborted **")
    exec_command = ["java", "-Xss16m", "-Xmx500m", classname]
elif language == 'perl':
    exec_command = ["perl", "-w", "./__tester__.pl" ]
elif language == 'ruby':
    exec_command = ["ruby", "-w", "./__tester__.rb" ]
elif language == 'php':
    exec_command = ["php", "./__tester__.php" ]
elif language == 'javascript':
    exec_command = ["node", "./__tester__.js" ]
elif language == 'golang':
    go_env = {}
    go_env["GOCACHE"]="/tmp/.go-cache"
    completedProc = subprocess.run([ "go", "build", "-o", "tester.exe",  filename ],env=go_env  )
    if completedProc.returncode != 0:
        raise Exception("** Golang Compilation failed. Testing aborted **")
    exec_command = ["./tester.exe"]
elif language == 'c#':
    cs_env = {}
    completedProc = subprocess.run([ "mcs",  "-out:tester.exe", filename ],env=cs_env  )
    if completedProc.returncode != 0:
        raise Exception("** C# Compilation failed. Testing aborted **")
    exec_command = ["./tester.exe"]
else: # Python doesn't need a compile phase
    exec_command = ["python3", "./__tester__.py"]

# Now run the code. Since this is a per-test template,
# stdin is already set up for the stdin text specified in the test case,
# so we can run the compiled program directly.

try:
    output = subprocess.check_output(exec_command, universal_newlines=True)
    print(output)
except subprocess.CalledProcessError as e:
    if e.returncode > 0:
        # Ignore non-zero positive return codes
        if e.output:
            print(e.output)
    else:
        # But negative return codes are signals - abort
        if e.output:
            print(e.output, file=sys.stderr)
        if e.returncode < 0:
            print("Task failed with signal", -e.returncode, file=sys.stderr)
        print("** Further testing aborted **", file=sys.stderr)

