import json
import sys
from datetime import datetime, date, time
from neo4j import GraphDatabase
from neo4j.exceptions import Neo4jError
from neo4j.graph import Node, Relationship, Path

# Try to import Neo4j temporal types (Date, DateTime, Time)
try:
    from neo4j.time import Date as Neo4jDate, DateTime as Neo4jDateTime, Time as Neo4jTime
    NEO4J_TEMPORAL_TYPES = (Neo4jDate, Neo4jDateTime, Neo4jTime)
except Exception:
    # Fallback if the driver version doesn't expose neo4j.time
    NEO4J_TEMPORAL_TYPES = ()

# Unified tuple of temporal types we treat the same way
TEMPORAL_TYPES = (datetime, date, time) + NEO4J_TEMPORAL_TYPES

neo4j_config = {
    'protocol': '{{ QUESTION.parameters.neo4j_protocol | default("neo4j+s") }}',
    'host': '{{ QUESTION.parameters.neo4j_host | default("localhost") }}',
    'port': {{ QUESTION.parameters.neo4j_port | default(7687) }},
    'user': '{{ QUESTION.parameters.neo4j_user | default("neo4j") }}',
    'password': '{{ QUESTION.parameters.neo4j_password | default("") }}',
    'database': '{{ QUESTION.parameters.neo4j_database | default("neo4j") }}'
}

uri = f"{neo4j_config['protocol']}://{neo4j_config['host']}:{neo4j_config['port']}"
student_answer = """{{ STUDENT_ANSWER | e('py') }}""".strip()

SEPARATOR = "#<ab@17943918#@>#"
MAX_LIST_ITEMS = 5
MAX_DISPLAY_RECORDS = 3
MAX_OUTPUT_LENGTH = 7000

def split_statements(cypher_code):
    """Split Cypher code on statement terminators (;) while preserving order."""
    if not cypher_code.strip():
        return []
    statements = []
    buffer = []
    for line in cypher_code.splitlines():
        buffer.append(line)
        if line.rstrip().endswith(';'):
            statement = '\n'.join(buffer).rstrip().rstrip(';').strip()
            if statement:
                statements.append(statement)
            buffer = []
    if buffer:
        statement = '\n'.join(buffer).strip()
        if statement:
            statements.append(statement)
    if not statements:
        statements.append(cypher_code.strip())
    return statements

def truncate_sequence(seq):
    """Return a serialised list with optional truncation marker."""
    if not isinstance(seq, (list, tuple, set)):
        return seq
    values = list(seq)
    truncated = len(values) > MAX_LIST_ITEMS
    subset = values[:MAX_LIST_ITEMS]
    rendered = [serialize_value(item) for item in subset]
    if truncated:
        rendered.append(f"... ({len(values) - MAX_LIST_ITEMS} more items)")
    return rendered

def format_relationship_cypher(rel):
    """Format a relationship in Cypher syntax: [:TYPE {props}]"""
    parts = [f"[:{rel.type}"]
    if len(rel) > 0:  # Has properties
        props = {k: serialize_value(v) for k, v in rel.items()}
        props_json = json.dumps(props, ensure_ascii=False)
        parts.append(f" {props_json}")
    parts.append("]")
    return "".join(parts)

class Neo4jEncoder(json.JSONEncoder):
    """Custom JSON encoder for Neo4j types."""
    def default(self, obj):
        if isinstance(obj, Node):
            return {
                "_type": "node",
                "id": obj.id,
                "labels": list(obj.labels),
                "properties": dict(obj)
            }
        elif isinstance(obj, Relationship):
            props = dict(obj)
            if props:
                return f"[:{obj.type} {json.dumps(props, ensure_ascii=False)}]"
            else:
                return f"[:{obj.type}]"
        elif isinstance(obj, Path):
            return {
                "_type": "path",
                "nodes": list(obj.nodes),
                "relationships": list(obj.relationships)
            }
        # Handle Python + Neo4j temporal types
        elif isinstance(obj, TEMPORAL_TYPES):
            # Prefer isoformat if available
            if hasattr(obj, "isoformat"):
                return obj.isoformat()
            # Some Neo4j types also expose iso_format()
            if hasattr(obj, "iso_format"):
                return obj.iso_format()
            return str(obj)
        return super().default(obj)

def serialize_value(value):
    """Convert Neo4j driver values into JSON-serialisable structures."""
    if isinstance(value, Node):
        return {
            "_type": "node",
            "id": value.id,
            "labels": list(value.labels),
            "properties": {k: serialize_value(v) for k, v in value.items()}
        }
    if isinstance(value, Relationship):
        # Format relationships in readable Cypher syntax
        props = {k: serialize_value(v) for k, v in value.items()}
        if props:
            return f"[:{value.type} {json.dumps(props, ensure_ascii=False, cls=Neo4jEncoder)}]"
        else:
            return f"[:{value.type}]"
    if isinstance(value, Path):
        return {
            "_type": "path",
            "nodes": truncate_sequence(list(value.nodes)),
            "relationships": truncate_sequence(list(value.relationships))
        }
    if isinstance(value, (list, tuple, set)):
        return truncate_sequence(value)
    if isinstance(value, dict):
        return {k: serialize_value(v) for k, v in value.items()}
    # Handle Python + Neo4j temporal types
    if isinstance(value, TEMPORAL_TYPES):
        if hasattr(value, "isoformat"):
            return value.isoformat()
        if hasattr(value, "iso_format"):
            return value.iso_format()
        return str(value)
    return value

def serialize_records(records):
    """Convert a list of record dictionaries to a formatted string."""
    if not records:
        return "[]"
    display_records = records[:MAX_DISPLAY_RECORDS]
    sections = []
    for idx, record in enumerate(display_records, start=1):
        converted = {key: serialize_value(val) for key, val in record.items()}
        sections.append(
            f"Record {idx}:\n"
            f"{json.dumps(converted, indent=2, ensure_ascii=False, cls=Neo4jEncoder)}"
        )
    if len(records) > MAX_DISPLAY_RECORDS:
        sections.append(f"... ({len(records) - MAX_DISPLAY_RECORDS} more records not shown)")
    return '\n'.join(sections)

def format_query_output(statement, result):
    """Render the result of a Cypher execution."""
    records = result.data()
    summary = result.consume()
    output_parts = []
    if records:
        output_parts.append(serialize_records(records))
    else:
        counters = summary.counters
        counter_labels = [
            ('nodes_created', 'nodes created'),
            ('nodes_deleted', 'nodes deleted'),
            ('relationships_created', 'relationships created'),
            ('relationships_deleted', 'relationships deleted'),
            ('properties_set', 'properties set'),
            ('labels_added', 'labels added'),
            ('labels_removed', 'labels removed'),
            ('indexes_added', 'indexes added'),
            ('indexes_removed', 'indexes removed'),
            ('constraints_added', 'constraints added'),
            ('constraints_removed', 'constraints removed'),
        ]
        stats = []
        for attr, label in counter_labels:
            value = getattr(counters, attr, 0)
            if value:
                stats.append(f"{label}: {value}")
        if getattr(counters, 'contains_updates', False) and not stats:
            stats.append("database updated")
        output_parts.append(' | '.join(stats) if stats else "No records returned.")
    text = '\n'.join(part for part in output_parts if part)
    return clamp_output(text)

def clamp_output(text):
    """Limit output length to avoid Moodle truncation."""
    if len(text) <= MAX_OUTPUT_LENGTH:
        return text
    return (
        f"{text[:MAX_OUTPUT_LENGTH]}\n"
        f"... (output truncated to stay within display limits, {len(text) - MAX_OUTPUT_LENGTH} chars omitted)"
    )


def execute_cypher_block(tx, cypher_code, collect_output=False):
    """Execute one or more Cypher statements within a transaction."""
    outputs = []
    for statement in split_statements(cypher_code):
        if not statement.strip():
            continue
        result = tx.run(statement)
        if collect_output:
            outputs.append(format_query_output(statement, result))
        else:
            result.consume()
    combined = '\n\n'.join(filter(None, outputs))
    return clamp_output(combined) if collect_output else combined

