                                    if 'Error: a ==' in log_str or 'Error: a !=' in log_str:
                                        assertion_details = log_str
                                        break

                                if reason:
                                    reason = str(reason).replace('\x1b[0m', '').replace('\x1b[31m', '').strip()

                                if assertion_details:
                                    expected = "Assertion to pass"
                                    got = f"Assertion failed: {assertion_details}"
                                elif reason:
