import json
import os
import re
import subprocess
import sys
import tempfile
from html.parser import HTMLParser

RAW_ANSWER = """{{ STUDENT_ANSWER | e('py') }}"""


def _exit_with_error(message):
    print(f"ERROR: {message}")
    sys.exit(1)


try:
    parsed_answer = json.loads(RAW_ANSWER)
except json.JSONDecodeError as exc:
    _exit_with_error(f"Unable to parse submission JSON ({exc})")

if isinstance(parsed_answer, dict):
    student_files = parsed_answer.get('files', [])
else:
    student_files = parsed_answer

if not isinstance(student_files, list):
    _exit_with_error("Submission must contain a 'files' list.")


class StudentProject:
    def __init__(self, files):
        self.records = []
        self.by_path = {}
        for entry in files:
            if not isinstance(entry, dict):
                continue
            path = (entry.get('path') or '').strip()
            if not path:
                continue
            normalized = path.replace('\\', '/')
            content = entry.get('content', '')
            record = {
                'path': normalized,
                'content': content,
                'extension': normalized.rsplit('.', 1)[-1].lower() if '.' in normalized else ''
            }
            self.records.append(record)
            self.by_path[normalized] = record

    def get_content(self, path, default=''):
        record = self.by_path.get(path)
        return record['content'] if record else default

    @staticmethod
    def _normalize_extensions(extensions):
        if not extensions:
            return []
        if isinstance(extensions, str):
            items = extensions.split(',')
        else:
            items = extensions
        normalized = []
        for item in items:
            if not isinstance(item, str):
                continue
            trimmed = item.strip().lower()
            if trimmed:
                normalized.append(trimmed)
        return normalized

    def _filter_candidates(self, candidates, pattern=None, extensions=None):
        filtered = list(candidates)
        if pattern:
            try:
                regex = re.compile(pattern)
                filtered = [rec for rec in filtered if regex.search(rec['path'])]
            except re.error:
                filtered = []
        if extensions:
            filtered = [rec for rec in filtered if rec['extension'] in extensions]
        return filtered

    @staticmethod
    def _looks_like_regex(text):
        if not text:
            return False
        if text.startswith('^') or text.endswith('$'):
            return True
        special_chars = set('*+?|[](){}^$\\')
        if any(ch in special_chars for ch in text):
            return True
        if '.*' in text or '\d' in text or '\w' in text:
            return True
        return False

    def select_files(self, target=None, extensions=None, pattern=None):
        ext_list = self._normalize_extensions(extensions)

        def merge_unique(items):
            unique = []
            seen = set()
            for rec in items:
                if not rec:
                    continue
                if rec['path'] not in seen:
                    unique.append(rec)
                    seen.add(rec['path'])
            return unique

        if target is None or (isinstance(target, str) and target.strip().lower() in ('*', 'any', 'all')):
            return self._filter_candidates(self.records, pattern, ext_list)

        if isinstance(target, str):
            target = target.strip()
            lower_target = target.lower()
            if lower_target.startswith('regex:'):
                regex_text = target[len('regex:'):]
                return self._filter_candidates(self.records, regex_text or pattern, ext_list)
            if self._looks_like_regex(target):
                return self._filter_candidates(self.records, target, ext_list)
            record = self.by_path.get(target)
            return self._filter_candidates([record] if record else [], pattern, ext_list)

        if isinstance(target, list):
            combined = []
            for item in target:
                combined.extend(self.select_files(item, extensions=ext_list, pattern=pattern))
            return merge_unique(combined)

        if isinstance(target, dict):
            nested_target = target.get('files') or target.get('file')
            nested_pattern = target.get('pattern') or target.get('regex') or pattern
            nested_ext = target.get('extensions') or ext_list
            return self.select_files(nested_target, extensions=nested_ext, pattern=nested_pattern)

        return self._filter_candidates(self.records, pattern, ext_list)

    def __bool__(self):
        return bool(self.records)


project = StudentProject(student_files)


class _ElementCollector(HTMLParser):
    def __init__(self):
        super().__init__()
        self.elements = []
        self._stack = []

    def handle_starttag(self, tag, attrs):
        attr_dict = {k.lower(): v for k, v in attrs}
        classes = attr_dict.get('class', '')
        parent = self._stack[-1] if self._stack else None
        element = {
            'tag': tag.lower(),
            'attrs': attr_dict,
            'classes': set(filter(None, re.split(r'\s+', classes.strip()))) if classes else set(),
            'id': attr_dict.get('id'),
            'text': '',
            'line': self.getpos()[0],
            'parent': parent,
            'ancestors': self._stack.copy()
        }
        self.elements.append(element)
        self._stack.append(element)

    def handle_endtag(self, tag):
        if self._stack:
            self._stack.pop()

    def handle_data(self, data):
        if not self._stack or not data:
            return
        for element in self._stack:
            element['text'] += data


class HTMLDocument:
    def __init__(self, text):
        parser = _ElementCollector()
        try:
            parser.feed(text)
        except Exception:
            pass
        self.elements = parser.elements

    def find(self, **criteria):
        return [elem for elem in self.elements if _element_matches(elem, criteria)]


def _element_matches(element, criteria):
    tag = criteria.get('tag')
    if tag and tag != '*' and element['tag'] != tag.lower():
        return False
    elem_id = criteria.get('id')
    if elem_id and element['id'] != elem_id:
        return False
    classes = criteria.get('classes')
    if classes:
        if isinstance(classes, str):
            class_list = [c.strip() for c in classes.split(',') if c.strip()]
        else:
            class_list = classes
        required = {c.strip() for c in class_list if c.strip()}
        if not required.issubset(element['classes']):
            return False
    attrs = criteria.get('attributes') or {}
    for key, expected in attrs.items():
        key_lower = key.lower()
        if isinstance(expected, dict):
            actual = element['attrs'].get(key_lower)
            regex = expected.get('regex')
            equals = expected.get('equals')
            contains = expected.get('contains')
            if regex:
                if not actual or not re.search(regex, actual):
                    return False
            elif equals is not None and actual != equals:
                return False
            elif contains and (not actual or contains not in actual):
                return False
        elif expected is True:
            # Attribute presence check: just verify attribute exists in the dict
            # (HTMLParser sets boolean attributes to None, so we check key existence)
            if key_lower not in element['attrs']:
                return False
        else:
            actual = element['attrs'].get(key_lower)
            if actual != expected:
                return False
    text_contains = criteria.get('text_contains')
    if text_contains:
        haystack = element['text'] or ''
        if isinstance(text_contains, str):
            values = [text_contains]
        else:
            values = text_contains
        for needle in values:
            if needle and needle not in haystack:
                return False
    return True


CSS_COMMENT_RE = re.compile(r'/\*.*?\*/', re.S)


def _parse_css_rules(content, offset_line=0):
    stripped = CSS_COMMENT_RE.sub('', content)
    rules = []
    i = 0
    length = len(stripped)
    while i < length:
        if stripped[i].isspace():
            i += 1
            continue
        selector_start = i
        while i < length and stripped[i] != '{':
            i += 1
        if i >= length:
            break
        selector_text = stripped[selector_start:i].strip()
        relative_line = stripped.count('\n', 0, selector_start) + 1
        line_number = offset_line + relative_line
        i += 1
        depth = 1
        block_start = i
        while i < length and depth > 0:
            char = stripped[i]
            if char == '{':
                depth += 1
            elif char == '}':
                depth -= 1
            i += 1
        if depth > 0:
            raise ValueError(f"Unclosed CSS block for selector '{selector_text}' at line {line_number}")
        block = stripped[block_start:i - 1]
        if selector_text.startswith('@'):
            nested_offset = offset_line + stripped.count('\n', 0, block_start)
            nested = _parse_css_rules(block, offset_line=nested_offset)
            rules.extend(nested)
            continue
        selectors = [s.strip() for s in selector_text.split(',') if s.strip()]
        declarations = {}
        for declaration in block.split(';'):
            if ':' not in declaration:
                continue
            prop, value = declaration.split(':', 1)
            prop = prop.strip().lower()
            value = value.strip()
            if prop:
                declarations[prop] = value
        for selector in selectors:
            rules.append({'selector': selector, 'properties': dict(declarations), 'line': line_number})
    return rules


VOID_HTML_TAGS = {
    'area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link',
    'meta', 'param', 'source', 'track', 'wbr'
}


NODE_HARNESS = r"""
const fs = require('fs');
const vm = require('vm');
const assert = require('assert').strict;

function serialise(value) {
    if (typeof value === 'string') {
        return value;
    }
    try {
        return JSON.stringify(value);
    } catch (err) {
        return String(value);
    }
}

if (process.argv.length < 3) {
    console.error('Payload path missing');
    process.exit(2);
}

const payload = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const logs = [];
const sandbox = {
    console: {
        log: (...args) => logs.push(args.map(serialise).join(' '))
    },
    assert,
    studentFiles: payload.studentFiles,
    exports: {},
    module: { exports: {} },
    setTimeout,
    clearTimeout
};

sandbox.global = sandbox;
sandbox.window = sandbox;
sandbox.document = payload.documentStub || {};

const context = vm.createContext(sandbox);

try {
    for (const file of payload.studentFiles) {
        vm.runInContext(file.content, context, { filename: file.path });
    }
    if (payload.setup) {
        vm.runInContext(payload.setup, context, { filename: 'test-setup.js' });
    }
    if (payload.testCode) {
        vm.runInContext(payload.testCode, context, { filename: 'test.js' });
    }
    fs.writeFileSync(payload.outputPath, JSON.stringify({ ok: true, logs }), 'utf8');
} catch (error) {
    const message = error && error.stack ? error.stack : String(error);
    fs.writeFileSync(payload.outputPath, JSON.stringify({ ok: false, message, logs }), 'utf8');
}
"""


class TestResult:
    __slots__ = ('success', 'message')

    def __init__(self, success, message):
        self.success = success
        self.message = message


class _SingleTagParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.attrs = {}

    def handle_starttag(self, tag, attrs):
        self.attrs = {k.lower(): v for k, v in attrs}


class StructuredTestRunner:
    def __init__(self, project):
        self.project = project
        self._html_cache = {}
        self._css_cache = {}
        self._line_offsets = {}

    def _pass_message(self, spec):
        desc = spec.get('description') if isinstance(spec, dict) else None
        custom = spec.get('message') or spec.get('success_message') if isinstance(spec, dict) else None
        if custom:
            return custom
        if desc:
            return desc
        return 'PASS'

    def _fail_message(self, spec, detail, file_path=None, line_number=None):
        detail = self._append_location(detail, file_path, line_number)
        return f"FAIL: {detail}"

    @staticmethod
    def _append_location(detail, file_path=None, line_number=None):
        if not file_path:
            return detail
        if line_number:
            return f"{detail} ({file_path}:{line_number})"
        return f"{detail} ({file_path})"

    def _resolve_scope(self, spec, default_ext=None):
        target = spec.get('files') or spec.get('file') or spec.get('scope') or spec.get('target')
        pattern = spec.get('pattern') or spec.get('file_pattern')
        extensions = spec.get('extensions') or spec.get('ext') or default_ext
        files = self.project.select_files(target, extensions=extensions, pattern=pattern)
        return files

    def _html_doc(self, path):
        if path not in self._html_cache:
            self._html_cache[path] = HTMLDocument(self.project.get_content(path, ''))
        return self._html_cache[path]

    def _css_doc(self, path):
        if path not in self._css_cache:
            try:
                self._css_cache[path] = _parse_css_rules(self.project.get_content(path, ''))
            except ValueError as e:
                import re
                match = re.search(r'at line (\d+)', str(e))
                line_number = int(match.group(1)) if match else None
                error_message = re.sub(r' at line \d+', '', str(e))
                self._css_cache[path] = {'error': error_message, 'line': line_number}
        return self._css_cache[path]

    def run(self, spec):
        mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()
        if mode == 'integration':
            steps = spec.get('steps') or []
            if not steps:
                return TestResult(False, self._fail_message(spec, 'Integration test is missing steps.'))
            for index, step in enumerate(steps, start=1):
                merged = dict(step)
                for inherit_key in ('files', 'file', 'scope', 'target', 'pattern', 'extensions'):
                    if inherit_key not in merged and inherit_key in spec:
                        merged[inherit_key] = spec[inherit_key]
                if 'description' not in merged and spec.get('description'):
                    merged['description'] = f"{spec['description']} (step {index})"
                if 'mode' not in merged:
                    merged['mode'] = merged.get('language') or merged.get('type') or spec.get('step_mode') or spec.get('step_language')
                result = self.run_single(merged)
                if not result.success:
                    # Strip "FAIL: " prefix from result.message to avoid double prefix
                    inner_message = result.message
                    if inner_message.startswith('FAIL: '):
                        inner_message = inner_message[6:]  # Remove "FAIL: " prefix
                    detail = f"Step {index} failed ({inner_message})"
                    return TestResult(False, self._fail_message(spec, detail))
            return TestResult(True, self._pass_message(spec))
        return self.run_single(spec)

    def run_single(self, spec):
        mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()
        if mode == 'html':
            return self._run_html(spec)
        if mode == 'css':
            return self._run_css(spec)
        if mode == 'js':
            return self._run_js(spec)
        return TestResult(False, self._fail_message(spec, f"Unknown mode '{mode}'."))

    def _run_html(self, spec):
        checks = spec.get('checks')
        if not checks:
            return TestResult(False, self._fail_message(spec, 'No HTML checks supplied.'))
        default_files = self._resolve_scope(spec, default_ext=['html', 'htm'])
        if not default_files:
            return TestResult(False, self._fail_message(spec, 'No HTML files matched the provided scope.'))
        for check in checks:
            files = default_files
            if isinstance(check, dict) and ('file' in check or 'files' in check):
                files = self._resolve_scope(check, default_ext=['html', 'htm']) or files
            selector = check.get('selector')
            criteria = dict(check)
            parsed_selector = None
            is_complex = False

            if selector and 'tag' not in criteria:
                parsed_selector = self._parse_selector(selector)
                is_complex = parsed_selector.get('complex', False)

            if is_complex:
                # Complex selector with combinators
                base_criteria = parsed_selector
            else:
                # Simple selector
                if parsed_selector:
                    selector_tag = parsed_selector.get('tag')
                    selector_id = parsed_selector.get('id')
                    selector_classes = parsed_selector.get('classes')
                    selector_attrs = parsed_selector.get('attributes')
                else:
                    selector_tag = selector_id = selector_classes = selector_attrs = None

                base_criteria = {}
                if selector_tag:
                    base_criteria['tag'] = selector_tag
                if selector_id:
                    base_criteria['id'] = selector_id
                if selector_classes:
                    base_criteria['classes'] = selector_classes
                if selector_attrs:
                    base_criteria['attributes'] = selector_attrs
                if 'tag' in criteria:
                    base_criteria['tag'] = criteria.pop('tag')
                if 'id' in criteria:
                    base_criteria['id'] = criteria.pop('id')

            property_fields = {}
            for field in ('classes', 'attributes', 'text_contains'):
                if field in criteria:
                    property_fields[field] = criteria.pop(field)

            forbid = bool(str(criteria.pop('forbid', criteria.pop('disallow', criteria.pop('prohibit', '')))).lower() in ('1', 'true', 'yes'))

            for meta_key in (
                'selector', 'file', 'files', 'scope', 'target', 'pattern', 'extensions',
                'message', 'description', 'mode', 'language', 'type', 'success_message',
                'property_message', 'structure_message'
            ):
                criteria.pop(meta_key, None)
            count_requirement = criteria.pop('count', None)
            min_requirement = criteria.pop('min', None)
            max_requirement = criteria.pop('max', None)
            matches = []
            for file in files:
                doc = self._html_doc(file['path'])
                if is_complex:
                    for element in doc.elements:
                        if self._matches_complex_selector(element, base_criteria):
                            matches.append((file['path'], element))
                else:
                    for element in doc.find(**base_criteria):
                        matches.append((file['path'], element))
            target_label = self._format_target_label(check, base_criteria)

            if not matches:
                # No matches found - this is success if forbidding or if max=0
                if forbid or max_requirement == 0:
                    continue
                message = check.get('message') or f"Element '{target_label}': not found."
                return TestResult(False, self._fail_message(spec, message, default_files[0]['path'] if default_files else None))

            if forbid:
                violating = []
                if property_fields:
                    for match in matches:
                        element = match[1]
                        ok, _ = self._check_property_requirements(element, property_fields)
                        if ok:
                            violating.append(match)
                else:
                    violating = matches
                if violating:
                    first_path, first_element = violating[0]
                    reason = check.get('forbid_message') or self._describe_forbidden_reason(target_label, property_fields)
                    return TestResult(False, self._fail_message(spec, reason, first_path, first_element.get('line')))
                continue

            if property_fields:
                property_matches = []
                property_error = None
                property_error_path = None
                property_error_line = None
                for match in matches:
                    file_path, element = match
                    ok, reason = self._check_property_requirements(element, property_fields)
                    if ok:
                        property_matches.append(match)
                    else:
                        property_error = reason
                        if property_error_path is None:
                            property_error_path = file_path
                            property_error_line = element.get('line')
                if not property_matches:
                    default_reason = property_error or 'required properties were missing.'
                    prop_message = (check.get('property_message') or check.get('message') or
                                    f"Element '{target_label}': {default_reason}")
                    return TestResult(False, self._fail_message(spec, prop_message, property_error_path, property_error_line))
                matches = property_matches

            structure_matches = []
            invalid_path = None
            invalid_line = None
            for file_path, element in matches:
                if self._element_structurally_valid(file_path, element):
                    structure_matches.append((file_path, element))
                elif invalid_path is None:
                    invalid_path = file_path
                    invalid_line = element.get('line')
            if not structure_matches:
                structure_message = (check.get('structure_message') or check.get('message') or
                                     f"Element '{target_label}': markup is malformed.")
                return TestResult(False, self._fail_message(spec, structure_message, invalid_path, invalid_line))
            matches = structure_matches

            # Apply count requirements after property and structure filtering.
            match_count = len(matches)
            sample_path = structure_matches[0][0] if structure_matches else None
            sample_line = structure_matches[0][1].get('line') if structure_matches else None
            if count_requirement is not None and match_count != count_requirement:
                message = f"Element '{target_label}': expected {count_requirement} matches, found {match_count}."
                return TestResult(False, self._fail_message(spec, message, sample_path, sample_line))
            if min_requirement is not None and match_count < min_requirement:
                message = f"Element '{target_label}': expected at least {min_requirement} matches, found {match_count}."
                return TestResult(False, self._fail_message(spec, message, sample_path, sample_line))
            if max_requirement is not None and match_count > max_requirement:
                if max_requirement == 0:
                    message = f"Element '{target_label}': should not exist, but found {match_count}."
                else:
                    message = f"Element '{target_label}': found {match_count} matches but maximum is {max_requirement}."
                return TestResult(False, self._fail_message(spec, message, sample_path, sample_line))
        return TestResult(True, self._pass_message(spec))

    def _parse_selector(self, selector):
        """Parse a CSS selector into a list of selector parts with combinators.

        Returns a list of dicts, where each dict represents a selector part.
        For simple selectors like 'a.button', returns a single-item list.
        For complex selectors like 'nav > a', returns multiple items with combinator info.
        """
        selector = selector.strip()

        # Split by combinators while preserving them
        # Handle: '>' (child), ' ' (descendant), '+' (adjacent sibling), '~' (general sibling)
        parts = []
        current = ''
        i = 0
        while i < len(selector):
            ch = selector[i]
            if ch == '>':
                if current.strip():
                    parts.append({'selector': current.strip(), 'combinator': '>'})
                current = ''
            elif ch in ['+', '~']:
                if current.strip():
                    parts.append({'selector': current.strip(), 'combinator': ch})
                current = ''
            elif ch == ' ':
                # Only treat as combinator if not inside brackets
                in_brackets = current.count('[') > current.count(']')
                if not in_brackets and current.strip():
                    parts.append({'selector': current.strip(), 'combinator': ' '})
                    current = ''
                    # Skip additional spaces
                    while i + 1 < len(selector) and selector[i + 1] == ' ':
                        i += 1
                elif in_brackets:
                    current += ch
                # else skip leading spaces
            else:
                current += ch
            i += 1

        if current.strip():
            parts.append({'selector': current.strip(), 'combinator': None})

        # If no combinators found, treat as simple selector
        if len(parts) == 1 and parts[0]['combinator'] is None:
            return self._parse_simple_selector(parts[0]['selector'])

        # Parse each part
        parsed_parts = []
        for part in parts:
            parsed = self._parse_simple_selector(part['selector'])
            parsed['combinator'] = part['combinator']
            parsed_parts.append(parsed)

        return {'complex': True, 'parts': parsed_parts}

    def _parse_simple_selector(self, selector):
        """Parse a simple selector (no combinators) into criteria."""
        result = {'classes': []}
        tag_match = re.match(r'^([a-zA-Z][\w-]*)', selector)
        if tag_match:
            result['tag'] = tag_match.group(1).lower()
        id_matches = re.findall(r'#([\w-]+)', selector)
        if id_matches:
            result['id'] = id_matches[-1]
        class_matches = re.findall(r'\.([\w-]+)', selector)
        if class_matches:
            result['classes'] = class_matches
        # Parse attribute selectors like [href='/home'] or [data-link]
        # Match: [attr], [attr=value], [attr="value"], [attr='value']
        attr_matches = re.findall(r'\[([a-zA-Z][\w-]*)(?:([~|^$*]?=)(?:"([^"]*)"|\'([^\']*)\'|([^\]]*)))?\]', selector)
        if attr_matches:
            attributes = {}
            for match in attr_matches:
                attr_name = match[0].lower()
                operator = match[1]
                # Get the value from whichever capture group matched (double-quoted, single-quoted, or unquoted)
                attr_value = match[2] or match[3] or match[4] or ''
                attr_value = attr_value.strip()

                if not operator:
                    # Attribute presence check: [data-link]
                    attributes[attr_name] = True
                elif operator == '=':
                    # Exact match: [href='/home']
                    attributes[attr_name] = attr_value
                elif operator == '*=':
                    # Contains: [class*='btn']
                    attributes[attr_name] = {'contains': attr_value}
                elif operator == '^=':
                    # Starts with: [href^='/']
                    attributes[attr_name] = {'regex': f'^{re.escape(attr_value)}'}
                elif operator == '$=':
                    # Ends with: [href$='.html']
                    attributes[attr_name] = {'regex': f'{re.escape(attr_value)}$'}
                elif operator == '~=':
                    # Word match: [class~='active']
                    attributes[attr_name] = {'regex': rf'\b{re.escape(attr_value)}\b'}
                elif operator == '|=':
                    # Starts with word: [lang|='en']
                    attributes[attr_name] = {'regex': f'^{re.escape(attr_value)}(-|$)'}
            result['attributes'] = attributes
        return result

    def _matches_complex_selector(self, element, parsed_selector):
        """Check if an element matches a complex selector with combinators."""
        if not parsed_selector.get('complex'):
            return False

        parts = parsed_selector['parts']
        if not parts:
            return False

        # Start from the last part (rightmost) and work backwards
        # The last part must match the element itself
        last_part = parts[-1]
        if not _element_matches(element, last_part):
            return False

        # If only one part, we're done
        if len(parts) == 1:
            return True

        # Work backwards through the parts
        current_element = element
        for i in range(len(parts) - 2, -1, -1):
            part = parts[i]
            combinator = parts[i + 1].get('combinator')

            if combinator == '>':
                # Direct child: parent must match
                if not current_element.get('parent'):
                    return False
                if not _element_matches(current_element['parent'], part):
                    return False
                current_element = current_element['parent']
            elif combinator == ' ':
                # Descendant: any ancestor must match
                found = False
                for ancestor in current_element.get('ancestors', []):
                    if _element_matches(ancestor, part):
                        current_element = ancestor
                        found = True
                        break
                if not found:
                    return False
            elif combinator == '+':
                # Adjacent sibling: not implemented yet
                return False
            elif combinator == '~':
                # General sibling: not implemented yet
                return False

        return True

    def _format_target_label(self, check, base_criteria):
        selector = check.get('selector')
        if selector:
            return selector
        tag = base_criteria.get('tag') or '*'
        label = tag
        element_id = base_criteria.get('id')
        if element_id:
            label += f"#{element_id}"
        classes = base_criteria.get('classes')
        if classes:
            if isinstance(classes, str):
                class_list = [c.strip() for c in classes.split(',') if c.strip()]
            else:
                class_list = list(classes)
            for cls in class_list:
                label += f".{cls}"
        return label

    def _element_structurally_valid(self, filepath, element):
        html = self.project.get_content(filepath, '')
        if not html:
            return False
        tag = (element.get('tag') or '').lower()
        if not tag:
            return False
        id_required = (element.get('id') or '').strip()
        class_required = set(element.get('classes') or [])
        attr_required = element.get('attrs') or {}

        start_index = self._find_element_start_index(filepath, html, tag, element.get('line'))
        if start_index is None:
            return False

        snippet, end_index = self._extract_start_tag(html, start_index)
        if not snippet:
            return False

        attr_map = self._parse_start_tag_attributes(tag, snippet)
        if id_required and attr_map.get('id') != id_required:
            return False
        if class_required:
            class_value = attr_map.get('class', '') or ''
            class_set = {c for c in re.split(r'\s+', class_value.strip()) if c}
            if not class_required.issubset(class_set):
                return False
        for key, value in attr_required.items():
            key = key.lower()
            if key in ('id', 'class'):
                continue
            if attr_map.get(key) != value:
                return False
        if tag not in VOID_HTML_TAGS:
            closing = f'</{tag}>'
            if closing.lower() not in html[end_index:].lower():
                return False
        return True

    def _check_property_requirements(self, element, property_fields):
        if not property_fields:
            return True, None

        if 'classes' in property_fields:
            required_classes = property_fields['classes']
            if isinstance(required_classes, str):
                required = {c.strip() for c in required_classes.split(',') if c.strip()}
            else:
                required = {str(c).strip() for c in required_classes if str(c).strip()}
            missing = [cls for cls in required if cls and cls not in element['classes']]
            if missing:
                return False, 'is missing required classes: ' + ', '.join(missing)

        attributes = property_fields.get('attributes') or {}
        for key, expected in attributes.items():
            attr_name = key.lower()
            actual = element['attrs'].get(attr_name)
            if actual is None:
                return False, f"is missing attribute '{attr_name}'"
            if isinstance(expected, dict):
                if 'equals' in expected:
                    expected_value = expected['equals']
                    if actual != expected_value:
                        return False, f"attribute '{attr_name}' must equal '{expected_value}'"
                elif 'contains' in expected:
                    needle = expected['contains']
                    if needle and needle not in actual:
                        return False, f"attribute '{attr_name}' must contain '{needle}'"
                elif 'regex' in expected:
                    pattern = expected['regex']
                    try:
                        if not re.search(pattern, actual):
                            return False, f"attribute '{attr_name}' must match /{pattern}/"
                    except re.error:
                        continue
                else:
                    if actual != expected:
                        return False, f"attribute '{attr_name}' does not match expected value"
            else:
                expected_value = str(expected)
                if actual != expected_value:
                    return False, f"attribute '{attr_name}' must equal '{expected_value}'"

        text_requirement = property_fields.get('text_contains')
        if text_requirement:
            haystack = element['text'] or ''
            values = [text_requirement] if isinstance(text_requirement, str) else text_requirement
            missing_text = [needle for needle in values if needle and needle not in haystack]
            if missing_text:
                if len(missing_text) == 1:
                    return False, f"must contain text '{missing_text[0]}'"
                return False, 'must contain text values: ' + ', '.join(missing_text)

        return True, None

    def _describe_forbidden_reason(self, target_label, property_fields):
        if property_fields:
            parts = []
            if 'classes' in property_fields:
                classes = property_fields['classes']
                if isinstance(classes, str):
                    class_list = [c.strip() for c in classes.split(',') if c.strip()]
                else:
                    class_list = [str(c).strip() for c in classes if str(c).strip()]
                if class_list:
                    parts.append('classes ' + ', '.join(class_list))
            attributes = property_fields.get('attributes') or {}
            attr_names = [k for k in attributes.keys()]
            if attr_names:
                parts.append('attributes ' + ', '.join(attr_names))
            text_req = property_fields.get('text_contains')
            if text_req:
                if isinstance(text_req, str):
                    text_list = [text_req]
                else:
                    text_list = [str(t) for t in text_req if str(t)]
                if text_list:
                    parts.append('text ' + ', '.join(text_list))
            if parts:
                detail = f"Element '{target_label}' must not include " + ' or '.join(parts) + '.'
            else:
                detail = f"Element '{target_label}' must not exist."
        else:
            detail = f"Element '{target_label}' must not exist."
        return detail

    def _describe_css_forbidden_reason(self, selector, properties, check):
        if properties:
            prop_names = [prop for prop in properties.keys()]
            if prop_names:
                return (check.get('forbid_message') or
                        f"Selector '{selector}' must not include properties: {', '.join(prop_names)}.")
            else:
                return (check.get('forbid_message') or
                        f"Selector '{selector}' must not exist.")
        else:
            return (check.get('forbid_message') or
                    f"Selector '{selector}' must not exist.")

    def _parse_start_tag_attributes(self, tag, snippet):
        parser = _SingleTagParser()
        try:
            parser.feed(snippet + f'</{tag}>')
        except Exception:
            return {}
        return parser.attrs

    def _find_element_start_index(self, filepath, html, tag, line):
        if filepath not in self._line_offsets:
            self._line_offsets[filepath] = self._compute_line_offsets(html)
        offsets = self._line_offsets[filepath]
        if not offsets:
            return None
        if not line or line < 1 or line > len(offsets):
            search_start = 0
        else:
            search_start = offsets[line - 1]
        lower_html = html.lower()
        token = f'<{tag}'.lower()
        index = lower_html.find(token, search_start)
        while index != -1:
            after = index + len(token)
            if after < len(html):
                next_char = lower_html[after]
                if next_char.isalnum() or next_char in ('-', ':'):
                    index = lower_html.find(token, after)
                    continue
            return index
        return None

    def _extract_start_tag(self, html, index):
        end = index + 1
        in_quote = None
        while end < len(html):
            ch = html[end]
            if in_quote:
                if ch == in_quote:
                    in_quote = None
            else:
                if ch in ('"', "'"):
                    in_quote = ch
                elif ch == '>':
                    snippet = html[index:end + 1]
                    return snippet, end + 1
                elif ch == '<' and end != index:
                    return None, None
            end += 1
        return None, None

    @staticmethod
    def _compute_line_offsets(text):
        if not text:
            return [0]
        offsets = []
        pos = 0
        for line in text.splitlines(keepends=True):
            offsets.append(pos)
            pos += len(line)
        if not text.endswith(('\n', '\r')):
            offsets.append(pos)
        return offsets

    def _run_css(self, spec):
        checks = spec.get('checks')
        if not checks:
            return TestResult(False, self._fail_message(spec, 'No CSS checks supplied.'))

        files = self._resolve_scope(spec, default_ext=['css', 'html'])
        if not files:
            return TestResult(False, self._fail_message(spec, 'No CSS or HTML files matched the provided scope.'))

        all_rules = []
        for file in files:
            content = self.project.get_content(file['path'], '')
            if not content:
                continue

            if file['extension'] == 'html':
                doc = self._html_doc(file['path'])
                style_elements = doc.find(tag='style')
                for style_element in style_elements:
                    style_content = style_element.get('text', '')
                    start_line = style_element.get('line', 1)
                    if style_content:
                        try:
                            rules = _parse_css_rules(style_content, offset_line=start_line - 1)
                            for rule in rules:
                                rule['path'] = file['path']
                            all_rules.extend(rules)
                        except ValueError as e:
                            return TestResult(False, self._fail_message(spec, f"CSS parsing error in {file['path']}: {e}", file['path'], start_line))
            elif file['extension'] == 'css':
                try:
                    rules = self._css_doc(file['path'])
                    if isinstance(rules, dict) and 'error' in rules:
                        return TestResult(False, self._fail_message(spec, rules['error'], file['path'], rules.get('line')))
                    for rule in rules:
                        rule['path'] = file['path']
                    all_rules.extend(rules)
                except ValueError as e:
                    return TestResult(False, self._fail_message(spec, f"CSS parsing error: {e}", file['path']))

        if not all_rules:
            return TestResult(False, self._fail_message(spec, 'No CSS rules found in the specified files.'))

        for check in checks:
            selector = check.get('selector')
            selector_regex = check.get('selector_regex')
            properties = check.get('properties') or {}
            single_property = check.get('property')
            if single_property and single_property not in properties:
                value = check.get('value') or check.get('equals')
                properties[single_property] = value
            forbid = bool(str(check.pop('forbid', check.pop('disallow', check.pop('prohibit', '')))).lower() in ('1,', 'true', 'yes'))
            min_requirement = check.get('min')
            max_requirement = check.get('max')
            matches = []

            for rule in all_rules:
                if selector and rule['selector'] != selector:
                    continue
                if selector_regex and not re.search(selector_regex, rule['selector']):
                    continue
                matches.append((rule.get('path', 'inline'), rule))

            if forbid:
                if not properties:
                    if matches:
                        sample_path = matches[0][0] if matches else None
                        line_number = matches[0][1].get('line') if matches else None
                        reason = self._describe_css_forbidden_reason(selector, properties, check)
                        return TestResult(False, self._fail_message(spec, reason, sample_path, line_number))
                else:
                    for file_path, rule in matches:
                        for property_name, expected in properties.items():
                            property_name = property_name.lower()
                            if rule['properties'].get(property_name) is not None:
                                line_number = rule.get('line')
                                reason = self._describe_css_forbidden_reason(selector, {property_name: expected}, check)
                                return TestResult(False, self._fail_message(spec, reason, file_path, line_number))
                continue

            if not matches:
                message = check.get('message') or f"Selector '{selector}': not found."
                scope_path = files[0]['path'] if files else None
                return TestResult(False, self._fail_message(spec, message, scope_path))

            match_count = len(matches)
            if min_requirement is not None and match_count < min_requirement:
                sample_path = matches[0][0] if matches else None
                sample_line = matches[0][1].get('line') if matches else None
                message = f"Selector '{selector}': expected at least {min_requirement} matches, found {match_count}."
                return TestResult(False, self._fail_message(spec, message, sample_path, sample_line))
            if max_requirement is not None and match_count > max_requirement:
                sample_path = matches[0][0] if matches else None
                sample_line = matches[0][1].get('line') if matches else None
                message = f"Selector '{selector}': found {match_count} matches but maximum is {max_requirement}."
                return TestResult(False, self._fail_message(spec, message, sample_path, sample_line))

            for property_name, expected in properties.items():
                property_name = property_name.lower()
                ok, property_path, failure_reason, line_number = self._check_css_property(matches, property_name, expected)
                if not ok:
                    if failure_reason == 'missing':
                        detail = check.get('message') or f"Selector '{selector}': missing property '{property_name}'."
                    else:
                        detail = check.get('message') or f"Selector '{selector}': property '{property_name}' has wrong value."
                    return TestResult(False, self._fail_message(spec, detail, property_path, line_number))

        return TestResult(True, self._pass_message(spec))

    def _check_css_property(self, matches, property_name, expected):
        fallback_path = matches[0][0] if matches else None
        first_match_line = matches[0][1].get('line') if matches else None
        for file_path, rule in matches:
            actual = rule['properties'].get(property_name)
            if actual is None:
                continue
            if self._compare_values(actual, expected):
                return True, file_path, None, rule.get('line') # ok, file_path, failure_reason, line_number
            return False, file_path, 'wrong_value', rule.get('line') # Property exists but is wrong
        return False, fallback_path, 'missing', first_match_line # Property is missing in all rules

    @staticmethod
    def _compare_values(actual, expected):
        if isinstance(expected, dict):
            equals = expected.get('equals')
            contains = expected.get('contains')
            regex = expected.get('regex')
            if equals is not None:
                return _normalise_css_value(actual) == _normalise_css_value(str(equals))
            if contains:
                return contains.lower() in actual.lower()
            if regex:
                try:
                    return re.search(regex, actual) is not None
                except re.error:
                    return False
            return False
        return _normalise_css_value(actual) == _normalise_css_value(str(expected))

    @staticmethod
    def _is_truthy(value):
        if isinstance(value, bool):
            return value
        if value is None:
            return False
        return str(value).strip().lower() in ('1', 'true', 'yes', 'on')

    @staticmethod
    def _to_int(value):
        if isinstance(value, int):
            return value
        try:
            return int(str(value).strip())
        except (ValueError, TypeError):
            return None

    def _collect_js_regex_checks(self, spec, js_spec):
        checks = spec.get('regexChecks') or js_spec.get('regexChecks')

        simple_patterns = None
        for key in ('regex', 'regexes', 'patterns', 'codeRegex', 'codePatterns'):
            if key in spec:
                simple_patterns = spec.get(key)
                break
            if key in js_spec:
                simple_patterns = js_spec.get(key)
                break

        pattern_checks = []
        if simple_patterns:
            if isinstance(simple_patterns, str):
                pattern_checks.append({'pattern': simple_patterns})
            elif isinstance(simple_patterns, list):
                for item in simple_patterns:
                    if isinstance(item, str):
                        pattern_checks.append({'pattern': item})
                    elif isinstance(item, dict):
                        pattern_checks.append(item)

        if pattern_checks:
            checks = (checks or []) + pattern_checks

        return checks or []

    @staticmethod
    def _regex_flags(flag_string):
        flags = 0
        if not flag_string:
            return flags
        for char in str(flag_string):
            if char.lower() == 'i':
                flags |= re.IGNORECASE
            elif char.lower() == 'm':
                flags |= re.MULTILINE
            elif char.lower() == 's':
                flags |= re.DOTALL
        return flags

    def _run_js_regex_checks(self, files, regex_checks, spec):
        if not regex_checks:
            return TestResult(True, self._pass_message(spec))

        for check in regex_checks:
            pattern = check.get('pattern') or check.get('regex')
            if not pattern:
                return TestResult(False, self._fail_message(spec, 'Regex check is missing a pattern.'))

            try:
                compiled = re.compile(pattern, self._regex_flags(check.get('flags') or check.get('options')))
            except re.error as exc:
                return TestResult(False, self._fail_message(spec, f"Invalid regex '{pattern}': {exc}"))

            matches = []
            for file in files:
                text = file.get('content') or ''
                for match in compiled.finditer(text):
                    line = text.count('\n', 0, match.start()) + 1
                    line += file.get('offset_line', 0)
                    matches.append((file.get('original_path') or file['path'], line))

            match_count = len(matches)
            exact = self._to_int(check.get('count'))
            min_requirement = self._to_int(check.get('min'))
            max_requirement = self._to_int(check.get('max'))
            if exact is not None:
                min_requirement = max_requirement = exact
            forbid = self._is_truthy(check.get('forbid') or check.get('disallow') or check.get('prohibit'))
            message = check.get('message')

            if forbid:
                if match_count > 0:
                    target_path, line_number = matches[0]
                    detail = message or f"Regex /{pattern}/ must not appear in the submission."
                    return TestResult(False, self._fail_message(spec, detail, target_path, line_number))
                continue

            if min_requirement is None and max_requirement is None:
                min_requirement = 1

            if min_requirement is not None and match_count < min_requirement:
                scope_path = (matches[0][0] if matches else (files[0].get('original_path') or files[0]['path']))
                if min_requirement == 1:
                    detail = message or f"Regex /{pattern}/ not found."
                else:
                    detail = message or f"Regex /{pattern}/ expected at least {min_requirement} matches, found {match_count}."
                return TestResult(False, self._fail_message(spec, detail, scope_path))

            if max_requirement is not None and match_count > max_requirement:
                target_path, line_number = matches[0]
                detail = message or f"Regex /{pattern}/ matched {match_count} times (maximum {max_requirement})."
                return TestResult(False, self._fail_message(spec, detail, target_path, line_number))

        return TestResult(True, self._pass_message(spec))

    def _run_js(self, spec):
        js_spec = spec.get('js') or {}
        test_code = spec.get('jsTest') or spec.get('test') or js_spec.get('test') or js_spec.get('code')
        regex_checks = self._collect_js_regex_checks(spec, js_spec)
        if not test_code and not regex_checks:
            return TestResult(False, self._fail_message(spec, 'JavaScript test: missing a test body or regex checks.'))

        setup_code = spec.get('jsSetup') or js_spec.get('setup') or ''
        timeout = spec.get('timeout') or js_spec.get('timeout') or 5

        files = self._resolve_scope(spec, default_ext=['js', 'html'])
        if not files:
            return TestResult(False, self._fail_message(spec, 'JavaScript test: No files matched the provided scope.'))

        js_files = []
        for file in files:
            if file['extension'] == 'js':
                js_files.append(file)
            elif file['extension'] == 'html':
                doc = self._html_doc(file['path'])
                script_elements = doc.find(tag='script')
                for i, script_element in enumerate(script_elements):
                    script_content = script_element.get('text', '')
                    start_line = script_element.get('line', 1)
                    if script_content:
                        js_files.append({
                            'path': f"{file['path']}_inline_script_{i+1}.js",
                            'content': script_content,
                            'original_path': file['path'],
                            'offset_line': start_line -1
                        })

        if not js_files:
            return TestResult(False, self._fail_message(spec, 'No JavaScript code found in the specified files.'))

        if regex_checks:
            regex_result = self._run_js_regex_checks(js_files, regex_checks, spec)
            if not regex_result.success:
                return regex_result
            if not test_code:
                return regex_result

        outcome = self._execute_js(js_files, test_code, setup_code, timeout, js_spec)

        if not outcome.get('ok'):
            original_message = outcome.get('message') or 'JavaScript assertion failed.'
            # Extract file and line information from the error stack trace
            file_path, line_number = self._extract_student_file_location(original_message, js_files)

            # Clean up the error message to remove Node.js internals
            cleaned_message = self._clean_test_js_error(original_message, js_files)

            # If no student file in stack trace, at least show which file(s) are being tested
            if not file_path and js_files:
                # First try to get regular student files (not inline scripts)
                student_files = [f['path'] for f in js_files if not f.get('original_path')]
                if student_files:
                    file_path = student_files[0]
                else:
                    # Fall back to inline scripts - show the HTML file they came from
                    inline_files = [f.get('original_path') for f in js_files if f.get('original_path')]
                    if inline_files:
                        file_path = inline_files[0]

            # If we have a file but no line number, try to find the relevant function/code location
            # Pass both original message and test code to extract function name
            if file_path and not line_number:
                line_number = self._find_relevant_js_line(original_message, test_code, js_files, file_path)

            # Check if cleaned message already contains a stack trace with the file reference
            # If so, don't append file:line again (avoids duplication)
            has_stack_trace_with_file = False
            if file_path and line_number:
                # Check for stack trace patterns:
                # Format 1: "at functionName (file.js:5:1)"
                # Format 2: "at file.js:5:1"
                escaped_path = re.escape(file_path)
                pattern1 = rf'at .+?\({escaped_path}:{line_number}[:\)]'
                pattern2 = rf'at {escaped_path}:{line_number}[:\)]'
                if re.search(pattern1, cleaned_message) or re.search(pattern2, cleaned_message):
                    has_stack_trace_with_file = True

            # Only append file:line if it's not already in a stack trace
            final_file = file_path if not has_stack_trace_with_file else None
            final_line = line_number if not has_stack_trace_with_file else None

            return TestResult(False, self._fail_message(spec, cleaned_message, final_file, final_line))

        expected_logs = spec.get('expectedLogs')
        if expected_logs is not None:
            actual_logs = outcome.get('logs', [])
            if actual_logs != expected_logs:
                message = f"Expected logs: {expected_logs}, but got: {actual_logs}"
                return TestResult(False, self._fail_message(spec, message))

        return TestResult(True, self._pass_message(spec))

    def _rewrite_js_stack_trace(self, message, files):
        lines = message.split('\n')
        new_lines = []
        file_map = {f['path']: f for f in files if 'original_path' in f}

        for line in lines:
            # Try to match first line format: "file.js:12" (without "at" prefix)
            # This appears at the start of Node.js error messages
            if ':' in line and not line.strip().startswith('at ') and not line.strip().startswith('//'):
                match = re.search(r'^(.*?):(\d+)\s*$', line.strip())
                if match:
                    script_path = match.group(1)
                    line_num = int(match.group(2))

                    found_file = None
                    for file_path_key in file_map:
                        if script_path.endswith(file_path_key) or script_path == file_path_key:
                            found_file = file_map[file_path_key]
                            break

                    if found_file:
                        original_path = found_file['original_path']
                        offset_line = found_file['offset_line']
                        new_line_num = offset_line + line_num
                        # Preserve any leading/trailing whitespace from original
                        indent = len(line) - len(line.lstrip())
                        new_line = ' ' * indent + f"{original_path}:{new_line_num}"
                        new_lines.append(new_line)
                        continue

            # Try to match "at functionName (/path/to/file.js:5:1)"
            match = re.search(r'at (.*?) \((.*?):(\d+):(\d+)\)', line)
            if match:
                function_name = match.group(1)
                script_path = match.group(2)
                line_num = int(match.group(3))
                col_num = int(match.group(4))

                found_file = None
                for file_path_key in file_map:
                    if script_path.endswith(file_path_key):
                        found_file = file_map[file_path_key]
                        break

                if found_file:
                    original_path = found_file['original_path']
                    offset_line = found_file['offset_line']
                    new_line_num = offset_line + line_num
                    new_line = f"    at {function_name} ({original_path}:{new_line_num}:{col_num})"
                    new_lines.append(new_line)
                else:
                    new_lines.append(line)
                continue

            # Try to match "at /path/to/file.js:5:1"
            match = re.search(r'at (.*?):(\d+):(\d+)', line)
            if match:
                script_path = match.group(1)
                line_num = int(match.group(2))
                col_num = int(match.group(3))

                found_file = None
                for file_path_key in file_map:
                    if script_path.endswith(file_path_key):
                        found_file = file_map[file_path_key]
                        break

                if found_file:
                    original_path = found_file['original_path']
                    offset_line = found_file['offset_line']
                    new_line_num = offset_line + line_num
                    new_line = f"    at {original_path}:{new_line_num}:{col_num}"
                    new_lines.append(new_line)
                else:
                    new_lines.append(line)
                continue

            new_lines.append(line)

        return '\n'.join(new_lines)

    def _extract_student_file_location(self, message, files):
        """Extract the first student file reference from a JS error stack trace.

        Returns a tuple (file_path, line_number) or (None, None) if no student file found.
        Skips test.js, test-setup.js, and internal Node.js files.
        """
        lines = message.split('\n')
        student_file_paths = set(f['path'] for f in files)

        # Also check for original_path (inline scripts from HTML)
        for f in files:
            if 'original_path' in f:
                student_file_paths.add(f['original_path'])

        for line in lines:
            # Match "at functionName (file.js:5:1)" or "at file.js:5:1"
            match = re.search(r'at (?:.*? \()?(.*?):(\d+):(\d+)\)?', line)
            if match:
                file_path = match.group(1)
                line_num = int(match.group(2))

                # Skip test files and Node internals
                if file_path in ('test.js', 'test-setup.js') or file_path.startswith('node:'):
                    continue

                # Check if this is a student file
                if any(file_path.endswith(student_path) or file_path == student_path
                       for student_path in student_file_paths):
                    return (file_path, line_num)

            # Also check first line format: "file.js:1" at the start of error
            if ':' in line and not line.strip().startswith('at '):
                match = re.search(r'^(.*?):(\d+)\s*$', line.strip())
                if match:
                    file_path = match.group(1)
                    line_num = int(match.group(2))

                    # Check if this is a student file (not test.js)
                    if file_path not in ('test.js', 'test-setup.js'):
                        if any(file_path.endswith(student_path) or file_path == student_path
                               for student_path in student_file_paths):
                            return (file_path, line_num)

        return (None, None)

    def _find_relevant_js_line(self, error_message, test_code, js_files, target_file_path):
        """Try to find a relevant line number in student code based on the error message.

        For ReferenceError/TypeError, tries to find where the referenced function/variable is defined.
        For AssertionError, tries to find the function being tested.
        """
        # Extract function/variable name from the error
        function_name = None

        # Try to extract from ReferenceError: "X is not defined"
        match = re.search(r'ReferenceError:\s+(\w+)\s+is not defined', error_message)
        if match:
            function_name = match.group(1)

        # Try to extract from the test code itself (e.g., "assert.strictEqual(cube(5), 125)")
        if not function_name and test_code:
            match = re.search(r'assert\.\w+\((\w+)\s*\(', test_code)
            if match:
                function_name = match.group(1)

        # Try to extract from assertion in error message
        if not function_name:
            match = re.search(r'assert\.\w+\((\w+)\s*\(', error_message)
            if match:
                function_name = match.group(1)

        # Try to extract from assertion error message mentioning a function call
        if not function_name:
            match = re.search(r'Expected.*?\n.*?(\w+)\s*\(', error_message)
            if match:
                function_name = match.group(1)

        if not function_name:
            return None

        # Find the file content
        file_content = None
        offset_line = 0
        for f in js_files:
            # Check if this is the target file
            if f['path'] == target_file_path or f.get('original_path') == target_file_path:
                file_content = f.get('content', '')
                offset_line = f.get('offset_line', 0)
                break

        if not file_content:
            # Try loading from project
            file_content = self.project.get_content(target_file_path, '')

        if not file_content:
            return None

        # Search for function definition
        lines = file_content.split('\n')
        patterns = [
            rf'^\s*function\s+{re.escape(function_name)}\s*\(',  # function name()
            rf'^\s*const\s+{re.escape(function_name)}\s*=',      # const name =
            rf'^\s*let\s+{re.escape(function_name)}\s*=',        # let name =
            rf'^\s*var\s+{re.escape(function_name)}\s*=',        # var name =
            rf'^\s*{re.escape(function_name)}\s*:\s*function',   # name: function
            rf'^\s*{re.escape(function_name)}\s*\(',             # name() in object
        ]

        function_start_line = None
        for i, line in enumerate(lines):
            for pattern in patterns:
                if re.search(pattern, line):
                    function_start_line = i
                    break
            if function_start_line is not None:
                break

        if function_start_line is None:
            return None

        # Found the function - now look for the return statement within it
        # Search forward from function definition, looking for return statement
        brace_count = 0
        in_function = False
        return_line = None

        for i in range(function_start_line, len(lines)):
            line = lines[i]

            # Track braces to know when we've exited the function
            if '{' in line:
                brace_count += line.count('{')
                in_function = True
            if '}' in line:
                brace_count -= line.count('}')
                if in_function and brace_count <= 0:
                    break  # Exited the function

            # Look for return statement
            if in_function and re.search(r'^\s*return\b', line):
                return_line = i
                break

        # If we found a return statement, use that line; otherwise use function definition
        target_line = return_line if return_line is not None else function_start_line
        return offset_line + target_line + 1  # +1 for 1-indexed line numbers

    def _clean_test_js_error(self, message, files):
        """Clean up error messages by removing unhelpful Node.js internals and test.js noise.

        Returns just the error message and relevant stack trace lines from student files.
        """
        lines = message.split('\n')
        if not lines:
            return message

        student_file_paths = set(f['path'] for f in files)
        for f in files:
            if 'original_path' in f:
                student_file_paths.add(f['original_path'])

        # Find the line with the actual error type (e.g., "ReferenceError:", "AssertionError:")
        error_line_idx = None
        for i, line in enumerate(lines):
            stripped = line.strip()
            # Look for error type declarations
            if any(err in stripped for err in [
                'Error:', 'AssertionError', 'TypeError', 'ReferenceError',
                'SyntaxError', 'RangeError'
            ]) and not stripped.startswith('at '):
                error_line_idx = i
                break

        if error_line_idx is None:
            return message

        result_lines = []

        # Add the error message and any detail lines (but skip node:assert:, test.js: prefixes)
        for i in range(error_line_idx, len(lines)):
            line = lines[i]
            stripped = line.strip()

            # Skip node:assert:, node:vm:, test.js: prefixes before the error message
            if stripped and ':' in stripped and not stripped.startswith('at '):
                # Check if this is a node: or test.js: prefix line (appears before actual error)
                if any(skip in stripped for skip in ['node:assert:', 'node:vm:', 'node:internal:']):
                    continue
                # Skip test.js:N at the very start (code snippet location, not helpful)
                if stripped.startswith('test.js:') and i < error_line_idx + 3:
                    continue

            # Stop collecting non-stack lines once we hit stack traces
            if stripped.startswith('at '):
                break

            result_lines.append(line)

        # Now collect relevant stack trace lines (only student files, skip test.js and node internals)
        for i in range(error_line_idx, len(lines)):
            line = lines[i]
            stripped = line.strip()

            if not stripped.startswith('at '):
                continue

            # Filter out ALL unhelpful stack frames
            if any(skip in stripped for skip in [
                'test.js:', 'test-setup.js:',
                'node:vm:', 'node:internal/', 'node:assert:',
                'runner.js:', 'Module._compile', 'Module.load',
                'Function._load', 'TracingChannel', 'wrapModuleLoad',
                'Object..js', 'diagnostics_channel', 'Script.runInContext',
                'Object.runInContext'
            ]):
                continue

            # Only keep student file references
            if any(student_path in stripped for student_path in student_file_paths):
                result_lines.append(line)

        return '\n'.join(result_lines)

    def _rewrite_js_syntax_error(self, message, files):
        lines = message.split('\n')
        if not lines:
            return message

        first_line = lines[0]
        file_map = {f['path']: f for f in files if 'original_path' in f}

        found_file = None
        offending_script_path = None
        for file_path_key in file_map:
            if file_path_key in first_line:
                found_file = file_map[file_path_key]
                offending_script_path = file_path_key
                break

        if found_file:
            match = re.search(re.escape(offending_script_path) + r':(\d+)', first_line)
            if match:
                line_num = int(match.group(1))
                original_path = found_file['original_path']
                offset_line = found_file['offset_line']
                new_line_num = offset_line + line_num

                # Reconstruct the first line
                new_first_line = first_line.replace(match.group(0), f"{original_path}:{new_line_num}", 1)
                lines[0] = new_first_line
                return '\n'.join(lines)

        return message

    def _execute_js(self, files, test_code, setup_code, timeout, js_spec):
        with tempfile.TemporaryDirectory() as tmpdir:
            harness_path = os.path.join(tmpdir, 'runner.js')
            payload_path = os.path.join(tmpdir, 'payload.json')
            output_path = os.path.join(tmpdir, 'result.json')
            with open(harness_path, 'w', encoding='utf-8') as handle:
                handle.write(NODE_HARNESS)
            payload = {
                'studentFiles': [{'path': f['path'], 'content': f['content']} for f in files],
                'testCode': test_code,
                'setup': setup_code,
                'outputPath': output_path,
                'documentStub': js_spec.get('document')
            }
            with open(payload_path, 'w', encoding='utf-8') as handle:
                json.dump(payload, handle)
            try:
                completed = subprocess.run(
                    ['node', harness_path, payload_path],
                    capture_output=True,
                    text=True,
                    timeout=max(1, min(30, int(timeout)))
                )
            except FileNotFoundError:
                return {'ok': False, 'message': 'Node.js runtime is unavailable on the grading server.'}
            except subprocess.TimeoutExpired:
                return {'ok': False, 'message': 'JavaScript test exceeded the allotted time limit.'}

            if completed.returncode != 0:
                stderr = completed.stderr.strip() or completed.stdout.strip() or 'Unknown Node.js error.'
                if completed.returncode == 2:
                    return {'ok': False, 'message': f'Node.js harness failed: {stderr}'}

                new_stderr = self._rewrite_js_syntax_error(stderr, files)
                return {'ok': False, 'message': new_stderr}

            if not os.path.exists(output_path):
                return {'ok': False, 'message': 'JavaScript harness did not produce a result file.'}
            with open(output_path, 'r', encoding='utf-8') as handle:
                data = json.load(handle)

            if not data.get('ok'):
                message = data.get('message', '')
                new_message = self._rewrite_js_stack_trace(message, files)
                data['message'] = new_message
            return data


def _normalise_css_value(value):
    return re.sub(r'\s+', ' ', value.strip()).lower()


structured_runner = StructuredTestRunner(project)


class HTMLValidator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.errors = []

    def error(self, message):
        self.errors.append(message)


def validate_html(html_content):
    validator = HTMLValidator()
    try:
        validator.feed(html_content)
    except Exception as exc:
        validator.errors.append(str(exc))
    return validator.errors


def list_student_files(target=None, pattern=None, extensions=None):
    return [rec['path'] for rec in project.select_files(target, extensions=extensions, pattern=pattern)]


def get_file_content(path):
    return project.get_content(path, '')


def find_html_elements(path=None, **criteria):
    files = project.select_files(path or None, extensions=['html', 'htm'])
    matches = []
    for file in files:
        doc = structured_runner._html_doc(file['path'])
        for element in doc.find(**criteria):
            matches.append({'file': file['path'], **element})
    return matches


def get_css_rules(path):
    return structured_runner._css_doc(path)


def run_js_assertions(test_code, files=None, setup=''):
    scope = {'files': files} if files else {}
    spec = {**scope, 'mode': 'js', 'jsTest': test_code, 'jsSetup': setup}
    result = structured_runner.run(spec)
    if not result.success:
        raise AssertionError(result.message)
    return result.message


def _promote_inline_check(spec):
    if not isinstance(spec, dict) or 'checks' in spec:
        return spec
    inline_keys = {
        'selector', 'tag', 'id', 'classes', 'attributes', 'text_contains',
        'count', 'min', 'max', 'properties', 'property', 'value', 'equals', 'message'
    }
    captured = {}
    for key in list(spec.keys()):
        if key in inline_keys:
            captured[key] = spec.pop(key)
    if not captured:
        return spec
    for numeric_key in ('count', 'min', 'max'):
        if numeric_key in captured and isinstance(captured[numeric_key], str):
            try:
                captured[numeric_key] = int(captured[numeric_key])
            except ValueError:
                pass
    mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()
    if mode == 'css' and 'properties' not in captured and 'property' in captured:
        value = captured.pop('value', captured.get('equals'))
        prop_name = captured.pop('property')
        if value is not None:
            captured['properties'] = {prop_name: value}
    spec['checks'] = [captured]
    return spec


def parse_structured_spec(extra_text):
    if not extra_text:
        return None
    extra_text = extra_text.strip()
    if not extra_text:
        return None
    if extra_text.startswith('{'):
        try:
            data = json.loads(extra_text)
        except json.JSONDecodeError:
            return None
        if isinstance(data, dict):
            if 'mode' not in data:
                for key in ('language', 'lang', 'type'):
                    if key in data:
                        data['mode'] = data[key]
                        break
            return _promote_inline_check(data) if data.get('mode') else None
        return None
    parts = [segment.strip() for segment in extra_text.split(';') if segment.strip()]
    if not parts:
        return None
    data = {}
    for part in parts:
        if ':' not in part:
            continue
        key, value = part.split(':', 1)
        data[key.strip().lower()] = value.strip()
    if not data:
        return None
    mapping = {'lang': 'mode', 'language': 'mode', 'type': 'mode'}
    for source, target in mapping.items():
        if source in data:
            data[target] = data[source]
            break
    if 'files' in data:
        data['files'] = [item.strip() for item in data['files'].split(',') if item.strip()]
    if 'extensions' in data:
        data['extensions'] = [item.strip() for item in data['extensions'].split(',') if item.strip()]
    return _promote_inline_check(data) if data.get('mode') else None


def build_test_context():
    return {
        '__builtins__': __builtins__,
        'project': project,
        'get_file_content': get_file_content,
        'validate_html': validate_html,
        'find_html_elements': find_html_elements,
        'get_css_rules': get_css_rules,
        'run_js_assertions': run_js_assertions,
        'list_student_files': list_student_files,
        'structured_runner': structured_runner,
    }


{% for TEST in TESTCASES %}
testcode = """{{ TEST.testcode | e('py') }}"""
extra = """{{ TEST.extra | e('py') }}"""

spec = parse_structured_spec(extra)
try:
    if spec:
        result = structured_runner.run(spec)
        message = result.message or ''
        if isinstance(message, str):
            message = message.strip()
        print(message)
    else:
        if not testcode.strip():
            print('ERROR: Test case has no structured spec or test code.')
        else:
            context = build_test_context()
            exec(compile(testcode, '<testcase>', 'exec'), context)
except Exception as exc:
    print(f"ERROR: {exc}")

{% if not loop.last %}
print('---')
{% endif %}
{% endfor %}

