class PHPCodeAnalyzer:
    """Analyze PHP code structure for architecture validation."""

    @staticmethod
    def extract_classes(php_content):
        """Extract class names, methods, and method bodies from PHP code."""
        classes = []
        class_pattern = r'class\s+(\w+)(?:\s+extends\s+\w+)?(?:\s+implements\s+[\w,\s]+)?\s*\{'
        method_pattern = r'(?:(?:public|protected|private|static|final)\s+)*function\s+(\w+)\s*\('

        for match in re.finditer(class_pattern, php_content):
            class_name = match.group(1)
            class_start = match.end()
            brace_count = 1
            pos = class_start
            class_end = len(php_content)
            while pos < len(php_content) and brace_count > 0:
                if php_content[pos] == '{':
                    brace_count += 1
                elif php_content[pos] == '}':
                    brace_count -= 1
                    if brace_count == 0:
                        class_end = pos
                pos += 1

            class_body = php_content[class_start:class_end]

            # First, extract class-level property instantiations (for context)
            class_property_map = {}
            property_pattern = r'\$this->(\w+)\s*=\s*new\s+([A-Z]\w+)\s*\('
            for prop_match in re.finditer(property_pattern, class_body):
                prop_name = prop_match.group(1)
                class_name_ref = prop_match.group(2)
                class_property_map[prop_name] = class_name_ref

            # Extract methods with their bodies
            method_names = []  # Backward compatibility
            method_details = []  # NEW: detailed method info

            for method_match in re.finditer(method_pattern, class_body):
                method_name = method_match.group(1)
                method_names.append(method_name)

                # Find method body using brace counting
                method_start = method_match.end()

                # Skip to opening brace
                while method_start < len(class_body) and class_body[method_start] != '{':
                    method_start += 1

                if method_start >= len(class_body):
                    # No body found (abstract method or syntax error)
                    method_details.append({
                        'name': method_name,
                        'body': '',
                        'calls': []
                    })
                    continue

                method_start += 1  # Move past the opening brace

                # Find method body end using brace counting
                brace_count = 1
                method_pos = method_start
                method_end = len(class_body)

                while method_pos < len(class_body) and brace_count > 0:
                    if class_body[method_pos] == '{':
                        brace_count += 1
                    elif class_body[method_pos] == '}':
                        brace_count -= 1
                        if brace_count == 0:
                            method_end = method_pos
                    method_pos += 1

                method_body = class_body[method_start:method_end]

                # Extract method calls from this method body with class context
                method_calls = PHPCodeAnalyzer.extract_method_calls(method_body, class_property_map)

                method_details.append({
                    'name': method_name,
                    'body': method_body,
                    'calls': method_calls
                })

            classes.append({
                'name': class_name,
                'methods': method_names,  # BACKWARD COMPATIBLE: list of names
                'method_details': method_details,  # NEW: detailed method info
                'body': class_body
            })

        return classes

    @staticmethod
    def extract_method_calls(php_code, class_property_map=None):
        """
        Extract all method calls from PHP code.

        Args:
            php_code: The PHP code to analyze
            class_property_map: Optional dict mapping property names to class names
                               (e.g., {'dao': 'TestDao'} from class-level analysis)

        Returns:
            List of dicts with format:
            [
                {'variable': 'userDao', 'method': 'findById', 'type': 'instance', 'class': 'UserDao'},
                {'class': 'UserDao', 'method': 'findAll', 'type': 'static'},
            ]
        """
        calls = []

        # Start with class-level property map (if provided)
        var_to_class = dict(class_property_map) if class_property_map else {}

        # Direct assignment: $var = new ClassName()
        instantiation_pattern = r'\$(\w+)\s*=\s*new\s+([A-Z]\w+)\s*\('
        for match in re.finditer(instantiation_pattern, php_code):
            var_name = match.group(1)
            class_name = match.group(2)
            var_to_class[var_name] = class_name

        # Property assignment: $this->property = new ClassName()
        property_instantiation_pattern = r'\$this->(\w+)\s*=\s*new\s+([A-Z]\w+)\s*\('
        for match in re.finditer(property_instantiation_pattern, php_code):
            property_name = match.group(1)
            class_name = match.group(2)
            var_to_class[property_name] = class_name

        # Instance method calls: Handle both $var->method() and $this->property->method()
        # Pattern for chained calls: $this->property->method()
        chained_pattern = r'\$this->(\w+)->(\w+)\s*\('
        for match in re.finditer(chained_pattern, php_code):
            property_name = match.group(1)
            method_name = match.group(2)
            # Try to determine the class from property instantiation
            class_name = var_to_class.get(property_name)
            call_info = {
                'variable': property_name,
                'method': method_name,
                'type': 'instance'
            }
            if class_name:
                call_info['class'] = class_name
            calls.append(call_info)

        # Simple instance method calls: $var->method() (but not $this->...)
        simple_instance_pattern = r'(?<!\$this->)\$(\w+)->(\w+)\s*\('
        for match in re.finditer(simple_instance_pattern, php_code):
            var_name = match.group(1)
            method_name = match.group(2)
            # Skip if this is $this (already handled above)
            if var_name == 'this':
                continue
            # Try to determine the class from instantiation
            class_name = var_to_class.get(var_name)
            call_info = {
                'variable': var_name,
                'method': method_name,
                'type': 'instance'
            }
            if class_name:
                call_info['class'] = class_name
            calls.append(call_info)

        # Static method calls: Class::method()
        static_pattern = r'([A-Z]\w+)::(\w+)\s*\('
        for match in re.finditer(static_pattern, php_code):
            calls.append({
                'class': match.group(1),
                'method': match.group(2),
                'type': 'static'
            })

        return calls

    @staticmethod
    def method_calls_class(method_body, class_suffix):
        """Check if a method calls any method from a class with given suffix."""
        calls = PHPCodeAnalyzer.extract_method_calls(method_body)

        for call in calls:
            if call['type'] == 'instance':
                # Check if variable name suggests class type (e.g., $userDao)
                if class_suffix.lower() in call['variable'].lower():
                    return True
            elif call['type'] == 'static':
                # Check if class name ends with suffix
                if call['class'].endswith(class_suffix):
                    return True

        return False

    @staticmethod
    def calls_class(php_content, class_suffix):
        """Check if PHP code instantiates or calls a class ending with suffix."""
        patterns = [
            rf'new\s+\w*{re.escape(class_suffix)}\s*\(',
            rf'\$\w*{re.escape(class_suffix.lower())}\s*->',
            rf'{re.escape(class_suffix)}::\w+',
        ]
        for pattern in patterns:
            if re.search(pattern, php_content, re.IGNORECASE):
                return True
        return False


class HTTPClient:
    """Make HTTP requests to student Flight APIs."""

    @staticmethod
    def request(url, method='GET', headers=None, body=None, timeout=5):
        """Make HTTP request and return parsed response."""
        if headers is None:
            headers = {}

        if body and isinstance(body, dict):
            body = json.dumps(body).encode('utf-8')
            headers['Content-Type'] = 'application/json'
        elif body and isinstance(body, str):
            body = body.encode('utf-8')

        req = urllib.request.Request(
            url,
            data=body,
            headers=headers,
            method=method
        )

        try:
            with urllib.request.urlopen(req, timeout=timeout) as response:
                status_code = response.getcode()
                response_headers = dict(response.headers)
                response_body = response.read().decode('utf-8')

                try:
                    response_json = json.loads(response_body)
                except json.JSONDecodeError:
                    response_json = None

                return {
                    'status': status_code,
                    'headers': response_headers,
                    'body': response_body,
                    'json': response_json
                }
        except urllib.error.HTTPError as e:
            return {
                'status': e.code,
                'headers': dict(e.headers),
                'body': e.read().decode('utf-8'),
                'json': None,
                'error': str(e)
            }
        except Exception as e:
            return {
                'status': 0,
                'headers': {},
                'body': '',
                'json': None,
                'error': str(e)
            }


class StructuredTestRunner:
    def __init__(self, project):
        self.project = project
        self._html_cache = {}
        self._css_cache = {}
        self._line_offsets = {}

    def _pass_message(self, spec):
        desc = spec.get('description') if isinstance(spec, dict) else None
        custom = spec.get('message') or spec.get('success_message') if isinstance(spec, dict) else None
        if custom:
            return custom
        if desc:
            return desc
        return 'PASS'

    def _fail_message(self, spec, detail, file_path=None, line_number=None):
        detail = self._append_location(detail, file_path, line_number)
        return f"FAIL: {detail}"

    @staticmethod
    def _append_location(detail, file_path=None, line_number=None):
        if not file_path:
            return detail
        if line_number:
            return f"{detail} ({file_path}:{line_number})"
        return f"{detail} ({file_path})"

    def _resolve_scope(self, spec, default_ext=None):
        target = spec.get('files') or spec.get('file') or spec.get('scope') or spec.get('target')
        pattern = spec.get('pattern') or spec.get('file_pattern')
        extensions = spec.get('extensions') or spec.get('ext') or default_ext
        files = self.project.select_files(target, extensions=extensions, pattern=pattern)
        return files

    def _html_doc(self, path):
        if path not in self._html_cache:
            self._html_cache[path] = HTMLDocument(self.project.get_content(path, ''))
        return self._html_cache[path]

    def _css_doc(self, path):
        if path not in self._css_cache:
            try:
                self._css_cache[path] = _parse_css_rules(self.project.get_content(path, ''))
            except ValueError as e:
                import re
                match = re.search(r'at line (\d+)', str(e))
                line_number = int(match.group(1)) if match else None
                error_message = re.sub(r' at line \d+', '', str(e))
                self._css_cache[path] = {'error': error_message, 'line': line_number}
        return self._css_cache[path]

    def run(self, spec):
        mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()
        if mode == 'integration':
            steps = spec.get('steps') or []
            if not steps:
                return TestResult(False, self._fail_message(spec, 'Integration test is missing steps.'))
            for index, step in enumerate(steps, start=1):
                merged = dict(step)
                for inherit_key in ('files', 'file', 'scope', 'target', 'pattern', 'extensions'):
                    if inherit_key not in merged and inherit_key in spec:
                        merged[inherit_key] = spec[inherit_key]
                if 'description' not in merged and spec.get('description'):
                    merged['description'] = f"{spec['description']} (step {index})"
                if 'mode' not in merged:
                    merged['mode'] = merged.get('language') or merged.get('type') or spec.get('step_mode') or spec.get('step_language')
                result = self.run_single(merged)
                if not result.success:
                    inner_message = result.message
                    if inner_message.startswith('FAIL: '):
                        inner_message = inner_message[6:]
                    detail = f"Step {index} failed ({inner_message})"
                    return TestResult(False, self._fail_message(spec, detail))
            return TestResult(True, self._pass_message(spec))
        return self.run_single(spec)

    def run_single(self, spec):
        mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()
        if mode == 'html':
            return self._run_html(spec)
        if mode == 'css':
            return self._run_css(spec)
        if mode == 'js':
            return self._run_js(spec)
        return TestResult(False, self._fail_message(spec, f"Unknown mode '{mode}'."))

    def _run_html(self, spec):
        # Simplified HTML test implementation (use full multifile_html logic in production)
        checks = spec.get('checks')
        if not checks:
            return TestResult(False, self._fail_message(spec, 'No HTML checks supplied.'))
        default_files = self._resolve_scope(spec, default_ext=['html', 'htm'])
        if not default_files:
            return TestResult(False, self._fail_message(spec, 'No HTML files matched the provided scope.'))
        # Simplified check logic
        return TestResult(True, self._pass_message(spec))

    def _run_css(self, spec):
        # Simplified CSS test implementation
        checks = spec.get('checks')
        if not checks:
            return TestResult(False, self._fail_message(spec, 'No CSS checks supplied.'))
        return TestResult(True, self._pass_message(spec))

    def _run_js(self, spec):
        # Simplified JS test implementation
        test_code = spec.get('jsTest') or spec.get('test')
        if not test_code:
            return TestResult(False, self._fail_message(spec, 'JavaScript test: missing test body.'))
        return TestResult(True, self._pass_message(spec))


class FlightTestRunner(StructuredTestRunner):
    """Extended test runner with PHP/Flight capabilities."""

    def __init__(self, project, lsp_base_url='', workspace_id=''):
        super().__init__(project)
        self.lsp_base_url = lsp_base_url
        self.workspace_id = workspace_id

    def run_single(self, spec):
        mode = (spec.get('mode') or spec.get('language') or spec.get('type') or '').lower()

        if mode == 'php_route':
            return self._run_php_route(spec)
        if mode == 'php_architecture':
            return self._run_php_architecture(spec)
        if mode == 'php_code':
            return self._run_php_code(spec)

        return super().run_single(spec)

    def _run_php_route(self, spec):
        """Test HTTP endpoint of student's Flight API."""
        route = spec.get('route')
        if not route:
            return TestResult(False, self._fail_message(spec, 'No route specified'))

        lsp_base = spec.get('lsp_base_url') or self.lsp_base_url
        if not lsp_base:
            return TestResult(False, self._fail_message(spec, 'LSP base URL not configured'))

        if not route.startswith('/'):
            route = '/' + route

        url = f"{lsp_base.rstrip('/')}/cr/{self.workspace_id}{route}"

        method = spec.get('method', 'GET').upper()
        headers = spec.get('headers', {})
        body = spec.get('body') or spec.get('data')
        timeout = spec.get('timeout', 10)

        response = HTTPClient.request(url, method, headers, body, timeout)

        if 'error' in response and response['status'] == 0:
            return TestResult(False, self._fail_message(
                spec,
                f"Failed to connect to API: {response['error']}"
            ))

        expected = spec.get('expected', {})

        expected_status = expected.get('status')
        if expected_status and response['status'] != expected_status:
            return TestResult(False, self._fail_message(
                spec,
                f"Expected status {expected_status}, got {response['status']}"
            ))

        expected_json = expected.get('json')
        if expected_json is not None:
            if response['json'] is None:
                return TestResult(False, self._fail_message(
                    spec,
                    "Expected JSON response, but response was not valid JSON"
                ))

            # Check if expected_json has special array validation options
            if isinstance(expected_json, dict) and expected_json.get('_is_schema_spec'):
                # Array-specific validation
                if not isinstance(response['json'], list):
                    return TestResult(False, self._fail_message(
                        spec,
                        f"Expected array response, got {type(response['json']).__name__}"
                    ))

                validation_error = self._validate_json_array(
                    response['json'],
                    expected_json,
                    path='response'
                )
                if validation_error:
                    return TestResult(False, self._fail_message(spec, validation_error))
            else:
                # Standard validation (object or array)
                validation_error = self._validate_json_structure(
                    response['json'],
                    expected_json,
                    path='response'
                )
                if validation_error:
                    return TestResult(False, self._fail_message(spec, validation_error))

        return TestResult(True, self._pass_message(spec))

    def _validate_json_array(self, actual, expected_spec, path=''):
        """Validate array responses with flexible options."""
        min_length = expected_spec.get('min_length', expected_spec.get('min'))
        max_length = expected_spec.get('max_length', expected_spec.get('max'))
        exact_length = expected_spec.get('length', expected_spec.get('count'))

        # Check array length constraints
        actual_length = len(actual)
        if exact_length is not None and actual_length != exact_length:
            return f"{path}: expected exactly {exact_length} items, got {actual_length}"
        if min_length is not None and actual_length < min_length:
            return f"{path}: expected at least {min_length} items, got {actual_length}"
        if max_length is not None and actual_length > max_length:
            return f"{path}: expected at most {max_length} items, got {actual_length}"

        # Get item validation spec
        item_spec = expected_spec.get('items', expected_spec.get('item_schema'))
        item_type = expected_spec.get('item_type')

        if not item_spec and not item_type:
            return None  # No item validation specified

        # Determine how many items to validate
        validate_first = expected_spec.get('validate_first', expected_spec.get('sample_size'))
        items_to_check = actual[:validate_first] if validate_first else actual

        # Validate each item
        for index, item in enumerate(items_to_check):
            # If item_type is specified, validate primitive type
            if item_type:
                if not self._check_json_type(item, item_type):
                    return f"{path}[{index}]: expected type {item_type}, got {type(item).__name__}"
            # Otherwise use structure validation
            elif item_spec:
                error = self._validate_json_structure(
                    item,
                    item_spec,
                    f"{path}[{index}]"
                )
                if error:
                    return error

        return None

    def _validate_json_structure(self, actual, expected, path=''):
        """Recursively validate JSON structure matches expectations."""
        # Handle array validation
        if isinstance(expected, list):
            if not isinstance(actual, list):
                return f"{path}: expected array, got {type(actual).__name__}"
            # If expected is a list with one item, validate all actual items against it
            if len(expected) == 1:
                for index, item in enumerate(actual):
                    error = self._validate_json_structure(
                        item,
                        expected[0],
                        f"{path}[{index}]"
                    )
                    if error:
                        return error
            # If expected is a list with multiple items, validate length matches
            elif len(expected) > 1:
                if len(actual) != len(expected):
                    return f"{path}: expected {len(expected)} items, got {len(actual)}"
                for index, (actual_item, expected_item) in enumerate(zip(actual, expected)):
                    error = self._validate_json_structure(
                        actual_item,
                        expected_item,
                        f"{path}[{index}]"
                    )
                    if error:
                        return error
            return None

        # Handle object validation
        if isinstance(expected, dict):
            # Check for sampled exact array validation (items are actual sample data)
            if '_is_sample_spec' in expected and isinstance(expected.get('items'), list):
                if not isinstance(actual, list):
                    return f"{path}: expected array, got {type(actual).__name__}"

                # Validate length constraints
                actual_length = len(actual)
                min_length = expected.get('min_length')
                max_length = expected.get('max_length')
                exact_length = expected.get('length')

                if exact_length is not None and actual_length != exact_length:
                    return f"{path}: expected exactly {exact_length} items, got {actual_length}"
                if min_length is not None and actual_length < min_length:
                    return f"{path}: expected at least {min_length} items, got {actual_length}"
                if max_length is not None and actual_length > max_length:
                    return f"{path}: expected at most {max_length} items, got {actual_length}"

                # Validate first N items match examples exactly
                sample_items = expected['items']
                validate_first = expected.get('validate_first', len(sample_items))
                items_to_validate = min(validate_first, len(sample_items), actual_length)

                for index in range(items_to_validate):
                    error = self._validate_json_structure(
                        actual[index],
                        sample_items[index],
                        f"{path}[{index}]"
                    )
                    if error:
                        return error

                return None

            # Regular object validation
            if not isinstance(actual, dict):
                return f"{path}: expected object, got {type(actual).__name__}"

            for key, expected_value in expected.items():
                if key not in actual:
                    return f"{path}.{key}: missing required key"

                if isinstance(expected_value, dict):
                    if 'type' in expected_value:
                        type_name = expected_value['type']
                        if not self._check_json_type(actual[key], type_name):
                            return f"{path}.{key}: expected type {type_name}, got {type(actual[key]).__name__}"
                    elif 'contains' in expected_value:
                        if expected_value['contains'] not in str(actual[key]):
                            return f"{path}.{key}: does not contain '{expected_value['contains']}'"
                    elif 'regex' in expected_value:
                        if not re.search(expected_value['regex'], str(actual[key])):
                            return f"{path}.{key}: does not match pattern '{expected_value['regex']}'"
                    elif 'equals' in expected_value:
                        if actual[key] != expected_value['equals']:
                            return f"{path}.{key}: expected {expected_value['equals']}, got {actual[key]}"
                    else:
                        error = self._validate_json_structure(
                            actual[key],
                            expected_value,
                            f"{path}.{key}"
                        )
                        if error:
                            return error
                elif isinstance(expected_value, list):
                    if not isinstance(actual[key], list):
                        return f"{path}.{key}: expected array, got {type(actual[key]).__name__}"
                    # Recursively validate array
                    error = self._validate_json_structure(
                        actual[key],
                        expected_value,
                        f"{path}.{key}"
                    )
                    if error:
                        return error
                else:
                    if actual[key] != expected_value:
                        return f"{path}.{key}: expected {expected_value}, got {actual[key]}"

            return None

        # Handle primitive value validation
        if actual != expected:
            return f"{path}: expected {expected}, got {actual}"

        return None

    @staticmethod
    def _check_json_type(value, type_name):
        """Check if value matches expected JSON type."""
        type_map = {
            'string': str,
            'integer': int,
            'number': (int, float),
            'boolean': bool,
            'array': list,
            'object': dict,
            'null': type(None)
        }
        expected_type = type_map.get(type_name.lower())
        if expected_type is None:
            return False
        return isinstance(value, expected_type)

    def _run_php_architecture(self, spec):
        """Validate 3-layer architecture (DAO, Service, Routes)."""
        layers_spec = spec.get('layers', {})
        check_separation = spec.get('check_separation', False)

        dao_spec = layers_spec.get('dao', {})
        service_spec = layers_spec.get('service', {})
        routes_spec = layers_spec.get('routes', {})

        dao_pattern = dao_spec.get('pattern', r'.*Dao\.php$')
        dao_files = self.project.select_files(pattern=dao_pattern, extensions='php')
        dao_min = dao_spec.get('min', 0)
        if dao_min and len(dao_files) < dao_min:
            return TestResult(False, self._fail_message(
                spec,
                f"Expected at least {dao_min} DAO file(s) matching '{dao_pattern}', found {len(dao_files)}"
            ))

        service_pattern = service_spec.get('pattern', r'.*Service\.php$')
        service_files = self.project.select_files(pattern=service_pattern, extensions='php')
        service_min = service_spec.get('min', 0)
        if service_min and len(service_files) < service_min:
            return TestResult(False, self._fail_message(
                spec,
                f"Expected at least {service_min} Service file(s) matching '{service_pattern}', found {len(service_files)}"
            ))

        routes_pattern = routes_spec.get('pattern', r'.*Routes\.php$')
        routes_files = self.project.select_files(pattern=routes_pattern, extensions='php')
        routes_min = routes_spec.get('min', 0)
        if routes_min and len(routes_files) < routes_min:
            return TestResult(False, self._fail_message(
                spec,
                f"Expected at least {routes_min} Routes file(s) matching '{routes_pattern}', found {len(routes_files)}"
            ))

        # NEW: Create cache for parsed results to avoid redundant parsing
        parsed_cache = {}

        if check_separation and routes_files:
            for route_file in routes_files:
                route_content = route_file['content']
                if PHPCodeAnalyzer.calls_class(route_content, 'Dao'):
                    return TestResult(False, self._fail_message(
                        spec,
                        f"Routes file '{route_file['path']}' calls DAO directly. Routes should only call Services.",
                        route_file['path']
                    ))

        # Validate DAO methods
        global_dao_methods = dao_spec.get('methods', [])
        file_dao_specs = dao_spec.get('files', [])

        # OPTIMIZATION: Only parse DAO files if there are method requirements
        if global_dao_methods or file_dao_specs:
            for dao_file in dao_files:
                # Parse and cache the result for later use
                classes = PHPCodeAnalyzer.extract_classes(dao_file['content'])
                parsed_cache[dao_file['path']] = classes
                if not classes:
                    if global_dao_methods or file_dao_specs:
                        return TestResult(False, self._fail_message(
                            spec,
                            f"DAO file '{dao_file['path']}' contains no classes",
                            dao_file['path']
                        ))
                    continue

                # Check if this file has specific requirements
                file_spec = None
                for fspec in file_dao_specs:
                    file_pattern = fspec.get('pattern', fspec.get('name'))
                    if file_pattern and re.search(file_pattern, dao_file['path']):
                        file_spec = fspec
                        break

                # Determine which methods to require for this file
                required_methods = file_spec.get('methods') if file_spec else global_dao_methods

                if required_methods:
                    for cls in classes:
                        missing = [m for m in required_methods if m not in cls['methods']]
                        if missing:
                            return TestResult(False, self._fail_message(
                                spec,
                                f"DAO class '{cls['name']}' missing required methods: {', '.join(missing)}",
                                dao_file['path']
                            ))

        # Validate Service methods
        global_service_methods = service_spec.get('methods', [])
        file_service_specs = service_spec.get('files', [])

        # OPTIMIZATION: Only parse Service files if there are method requirements
        if global_service_methods or file_service_specs:
            for svc_file in service_files:
                # Parse and cache the result for later use
                classes = PHPCodeAnalyzer.extract_classes(svc_file['content'])
                parsed_cache[svc_file['path']] = classes
                if not classes:
                    if global_service_methods or file_service_specs:
                        return TestResult(False, self._fail_message(
                            spec,
                            f"Service file '{svc_file['path']}' contains no classes",
                            svc_file['path']
                        ))
                    continue

                # Check if this file has specific requirements
                file_spec = None
                for fspec in file_service_specs:
                    file_pattern = fspec.get('pattern', fspec.get('name'))
                    if file_pattern and re.search(file_pattern, svc_file['path']):
                        file_spec = fspec
                        break

                # Determine which methods to require for this file
                required_methods = file_spec.get('methods') if file_spec else global_service_methods

                if required_methods:
                    for cls in classes:
                        missing = [m for m in required_methods if m not in cls['methods']]
                        if missing:
                            return TestResult(False, self._fail_message(
                                spec,
                                f"Service class '{cls['name']}' missing required methods: {', '.join(missing)}",
                                svc_file['path']
                            ))

        # NEW: Validate method call requirements
        result = self._validate_method_calls(spec, layers_spec, dao_files, service_files, routes_files, parsed_cache)
        if not result.success:
            return result

        return TestResult(True, self._pass_message(spec))

    def _validate_method_calls(self, spec, layers_spec, dao_files, service_files, routes_files, parsed_cache):
        """
        Validate that specific methods call other specific methods.

        Supports validation of method-to-method call requirements.
        """
        # Validate DAO method calls (if specified)
        dao_spec = layers_spec.get('dao', {})
        if 'method_calls' in dao_spec:
            result = self._validate_layer_method_calls(
                spec, dao_files, dao_spec['method_calls'], 'DAO', parsed_cache
            )
            if not result.success:
                return result

        # Validate Service method calls (if specified)
        service_spec = layers_spec.get('service', {})
        if 'method_calls' in service_spec:
            result = self._validate_layer_method_calls(
                spec, service_files, service_spec['method_calls'], 'Service', parsed_cache
            )
            if not result.success:
                return result

        # Validate Routes method calls (if specified)
        routes_spec = layers_spec.get('routes', {})
        if 'method_calls' in routes_spec:
            result = self._validate_layer_method_calls(
                spec, routes_files, routes_spec['method_calls'], 'Routes', parsed_cache
            )
            if not result.success:
                return result

        return TestResult(True, self._pass_message(spec))

    def _validate_layer_method_calls(self, spec, layer_files, method_calls_spec, layer_name, parsed_cache):
        """
        Validate method call requirements for a specific layer.

        method_calls_spec format:
        {
            "getUserById": {
                "calls": ["findById"],
                "from_class": "UserDao",  # Optional: specific class
                "in_file": "UserService.php"  # Optional: specific file pattern
            }
        }
        """
        # Track which required methods we've found
        required_method_names = set(method_calls_spec.keys())
        found_method_names = set()

        for file_entry in layer_files:
            # OPTIMIZATION: Use cached parse result if available, otherwise parse now
            if file_entry['path'] in parsed_cache:
                classes = parsed_cache[file_entry['path']]
            else:
                classes = PHPCodeAnalyzer.extract_classes(file_entry['content'])
                parsed_cache[file_entry['path']] = classes

            for cls in classes:
                # Use new method_details instead of old methods list
                method_details = cls.get('method_details', [])

                for method_info in method_details:
                    method_name = method_info['name']

                    # Check if this method has call requirements
                    if method_name in method_calls_spec:
                        requirement = method_calls_spec[method_name]
                        in_file = requirement.get('in_file')

                        # If in_file is specified, check if current file matches
                        if in_file:
                            # Use regex to match file pattern
                            file_pattern = in_file.replace('.', r'\.').replace('*', '.*')
                            if not re.search(file_pattern, file_entry['path']):
                                # Method found but in wrong file, skip it
                                continue

                        # Method found in the right file (or no file restriction)
                        found_method_names.add(method_name)

                        required_calls = requirement.get('calls', [])
                        from_class = requirement.get('from_class')

                        # Get actual calls made by this method
                        actual_calls = method_info.get('calls', [])

                        # Validate each required call
                        for required_call in required_calls:
                            found = False

                            for call in actual_calls:
                                # Check if the method name matches
                                if call['method'] == required_call:
                                    # If from_class specified, check it matches
                                    if from_class:
                                        # Check if we have explicit class information
                                        if call.get('class') == from_class:
                                            found = True
                                            break
                                        # Fallback: check if variable name contains class name
                                        elif call['type'] == 'instance':
                                            var_lower = call['variable'].lower()
                                            class_lower = from_class.lower()
                                            if class_lower in var_lower:
                                                found = True
                                                break
                                    else:
                                        # No class specified, just check method name
                                        found = True
                                        break

                            if not found:
                                error_msg = f"{layer_name} method '{cls['name']}::{method_name}' must call '{required_call}'"
                                if from_class:
                                    error_msg += f" from class '{from_class}'"
                                return TestResult(False, self._fail_message(
                                    spec,
                                    error_msg,
                                    file_entry['path']
                                ))

        # Check if any required methods were missing
        missing_methods = required_method_names - found_method_names
        if missing_methods:
            missing_list = ', '.join(sorted(missing_methods))
            # Build detailed error message showing which files were expected
            error_parts = [f"{layer_name} layer missing required methods:"]
            for method in sorted(missing_methods):
                requirement = method_calls_spec[method]
                in_file = requirement.get('in_file')
                if in_file:
                    error_parts.append(f"  - {method} (expected in file matching '{in_file}')")
                else:
                    error_parts.append(f"  - {method}")
            error_msg = '\n'.join(error_parts)
            return TestResult(False, self._fail_message(
                spec,
                error_msg
            ))

        return TestResult(True, self._pass_message(spec))

    def _run_php_code(self, spec):
        """Validate PHP code patterns."""
        php_files = self._resolve_scope(spec, default_ext=['php'])
        if not php_files:
            return TestResult(False, self._fail_message(spec, 'No PHP files matched'))

        checks = spec.get('checks') or []
        if not checks and spec.get('pattern'):
            checks = [{'pattern': spec['pattern']}]

        for check in checks:
            pattern = check.get('pattern')
            if not pattern:
                continue

            flags = check.get('flags', '')
            regex_flags = 0
            if 'i' in flags:
                regex_flags |= re.IGNORECASE
            if 'm' in flags:
                regex_flags |= re.MULTILINE
            if 's' in flags:
                regex_flags |= re.DOTALL

            forbid = check.get('forbid', False)
            min_count = check.get('min')
            max_count = check.get('max')
            exact_count = check.get('count')

            total_matches = 0
            for php_file in php_files:
                matches = len(re.findall(pattern, php_file['content'], regex_flags))
                total_matches += matches

            if forbid and total_matches > 0:
                msg = check.get('message', f"Pattern '{pattern}' should not appear in PHP code")
                return TestResult(False, self._fail_message(spec, msg))

            if exact_count is not None and total_matches != exact_count:
                msg = f"Pattern '{pattern}': expected {exact_count} matches, found {total_matches}"
                return TestResult(False, self._fail_message(spec, msg))

            if min_count is not None and total_matches < min_count:
                msg = f"Pattern '{pattern}': expected at least {min_count} matches, found {total_matches}"
                return TestResult(False, self._fail_message(spec, msg))

            if max_count is not None and total_matches > max_count:
                msg = f"Pattern '{pattern}': expected at most {max_count} matches, found {total_matches}"
                return TestResult(False, self._fail_message(spec, msg))

        return TestResult(True, self._pass_message(spec))


