    # Prepare deployment payload (filter out hidden stub files)
    deployment_files = []
    for file_entry in student_files:
        path = file_entry.get('path', '')
        # Skip hidden stub files (starting with underscore)
        if path and not re.match(r'^/?_[^/]+\.php$', path):
            deployment_files.append({
                'path': path,
                'content': file_entry.get('content', ''),
                'locked': False,
                'uid': 'null'
            })

    payload = {
        'folderName': workspace_id,
