def parse_structured_spec(extra_text):
    if not extra_text:
        return None
    extra_text = extra_text.strip()
    if not extra_text:
        return None
    if extra_text.startswith('{'):
        try:
            data = json.loads(extra_text)
        except json.JSONDecodeError:
            return None
        if isinstance(data, dict):
            if 'mode' not in data:
                for key in ('language', 'lang', 'type'):
                    if key in data:
                        data['mode'] = data[key]
                        break
            return data if data.get('mode') else None
        return None
    return None


